pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo penalty: favor bin configurations that leave room for common item sizes
    // We penalize residuals that are small but unusable (1..9 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: If next_item_size is large, favor larger post_residuals
    // If next_item_size is small, favor tightest fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin cannot fit the next item, penalize if it's the only fitting bin
            score += 20.0 / (fitting_bins_count as f64 + 1.0);
        } else {
            // This bin can fit the next item, reward this
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 4. Modulo/Harmonic bias: Favor residuals that align with common fractions of C
    // 100/2=50, 100/3=33, 100/4=25. If post_residual is near these, it's a "good" state.
    let harmonic_bias = ((post_residual % 25) as f64).abs();
    score += harmonic_bias * 0.2;

    // 5. Global state normalization:
    // If we are late in the stream, be more aggressive about filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 2.0;

    // 6. New Bin Threshold:
    // If bin_residual == bin_capacity, this is a new bin.
    // Penalty is high to force Best-Fit behavior, but decreases as open_bins_count grows.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64 * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" small residuals that are unlikely to fit future items.
    // We penalize residuals in the range [1, 15] heavily as they are often dead space.
    if post_residual > 0 && post_residual < 16 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it's a "tight" fit for the next item.
        if post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    }

    // 3. Penalty for opening a new bin prematurely.
    // If this is a new bin (bin_residual == bin_capacity), only choose it if no other bins fit
    // or if the existing bins are extremely crowded.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 4. Harmonic balancing: Prefer bins that keep the mean residual stable.
    // If post_residual is significantly lower than the mean, we are "tightening" the bin.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression awareness: As we near the end of the stream, prioritize packing density.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (1-9 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: Reward placements that leave exactly enough space for next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // Perfect fit for next item
        } else if post_residual > next_item_size {
            // Penalize leaving a gap that is slightly too small for the next item
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
        }
    }

    // 3. Pressure management: If this is the only fitting bin, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 4. Global balance: Penalize deviations from the mean residual to keep bins packed evenly
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression scaling: As we reach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we approach end of stream
        score += 25.0 * progress;
        // But lower the penalty if we have many bins open already
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is small (1-9), it is likely unusable.
    // Penalty scales quadratically as we approach zero residual.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powi(2) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize post_residuals
    // that are too small to fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: Penalize opening new bins heavily unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost
    // that decreases as the number of open bins increases to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 40.0 - (open_bins_count as f64 * 0.5);
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item,
    // lower the score to force selection and avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global efficiency: Favor bins that keep the mean_residual higher
    // to preserve flexibility for larger items later in the stream.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor post_residuals that are multiples of common item sizes (20, 25, 33)
    // to keep bins "open" for future items of similar classes.
    let harmonic_alignment = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_alignment * 0.5;

    // 2. Lookahead Coupling: If next_item_size is large, penalize small post_residuals.
    // If next_item_size is small, reward keeping a residual that fits the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for creating a bin that cannot fit the immediate next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward the "Perfect Fit" window for the next item
            score -= (post_residual - next_item_size) as f64 * 0.8;
        }
    }

    // 3. Density Balancing: If we have many open bins, prioritize closing gaps (Best Fit).
    // If we have few open bins, prioritize keeping space open (First Fit/Worst Fit hybrid).
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += density_factor * 2.0;

    // 4. Last Chance Logic: If this is the only bin that fits the current item, 
    // force its selection by applying a massive discount.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current best fit 
    // is truly inefficient (e.g., leaving a tiny, unusable sliver).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low, 
        // suggesting current bins are too fragmented to be useful.
        if mean_residual > 15.0 {
            score -= 10.0; 
        } else {
            score += 100.0; // Heavily penalize opening new bins when space is available
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (dead space too small for smallest items)
    // We heavily penalize residuals between 1 and 9 (the lower bound of item sizes)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if we have a next item, check if it fits in the current post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Best-Fit-Lookahead)
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a bin that cannot fit the next item if we have other options
            score += 15.0;
        }
    }

    // Global state awareness: 
    // If we have many open bins, prioritize tightening existing ones.
    // If we are near the end of the stream, be more aggressive about filling current bins.
    score += (open_bins_count as f64 * 2.0) * (1.0 - progress);

    // Dynamic constraint: 
    // If this is the only bin that fits, we are forced to take it unless it's a terrible fit.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New bin thresholding:
    // Only open a new bin if the current bin's post_residual is significantly worse 
    // than the global average residual, or if we are forced.
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High cost to open a new bin unless the current fit quality is poor
            score = 85.0 + (mean_residual * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best Fit).
    // Penalize large post_residual to keep bins tightly packed.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, 
    // heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 50.0;
    }

    // 3. Harmonic classes / Residual pressure: 
    // Penalize small "dead" residuals that are unlikely to fit future items (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; 
    }

    // 4. New Bin Policy: 
    // If this is a new bin (residual == capacity), add a high base cost.
    // Only pick if fitting_bins_count is low or current fits are extremely poor.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If we have many open bins, prefer using them over opening a new one.
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Global density balancing: 
    // If the bin's residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 25.0;
    }

    // 6. Last chance logic: 
    // If this is the only bin that fits, reduce penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: The remaining space after placement. Smaller is generally better (Best Fit).
    // post_residual == 0 is the "perfect fit" ideal.

    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items.
    // If post_residual is between 1 and 9, it's highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this bin.
    // This effectively implements a basic Best-Fit-Decreasing style lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Dynamic Time Horizon: As we near the end of the stream, prioritize closing bins
    // over opening new ones to reduce the total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Heavily penalize opening a new bin late in the game
        if bin_residual == bin_capacity {
            score += 100.0;
        }
    }

    // Global State: If the bin residual is significantly above the mean, 
    // it suggests this bin is "emptier" than others. We prefer to fill "emptier" bins 
    // to keep the mean residual balanced across the set.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    // New Bin Handling: Only open a new bin if the current fit is catastrophic (e.g., > 40 waste).
    if bin_residual == bin_capacity {
        if post_residual > 40 {
            score -= 30.0; 
        } else {
            // Otherwise, strongly discourage opening a new bin unnecessarily
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Class Logic: Reward placements that leave residuals 
    // which are multiples of common item sizes (alignment with modular arithmetic).
    // This reduces fragmentation by creating "compatible" gaps.
    let remainder = post_residual % 20;
    score += (remainder as f64).powi(2) * 0.1;

    // 3. Lookahead Logic: If the next item fits into the current post_residual,
    // strongly incentivize this bin to preserve bin count.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Threshold Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Empty Bin Penalty: Discourage opening a new bin unless the fit is excellent.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the item is very large, opening a new bin is less penalized.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // 6. Global density pressure: As we approach the end of the stream, 
    // tighten the requirements for opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating a "fragment" bin (a bin that is almost empty but not quite usable)
    // We penalize small residuals that are too large to fit the next item but too small to be useful
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res) * 1.5;
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter to avoid late-stage bin proliferation
    // We use a non-linear scaling factor based on progress to increase the cost of leaving space
    let packing_pressure = (progress.powf(2.0) * 10.0) + (open_bins_count as f64 * 0.5);
    score += post_res * packing_pressure * 0.05;

    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low, 
        // suggesting current bins are too tight to accommodate future items effectively
        let new_bin_penalty = 25.0 + (mean_residual * 0.5) - (progress * 10.0);
        score = new_bin_penalty;
    } else {
        // If it's an existing bin, reward bins that align with the mean residual 
        // to keep bin states uniform (prevents high-variance bin states)
        let residual_variance_penalty = (post_res - mean_residual).abs() * 0.2;
        score += residual_variance_penalty;
    }

    // Criticality check: If this is the only bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best-Fit principle).
    // The base score is already post_residual.

    // 2. Harmonic Penalty: Penalize remnants that are too small to fit future items.
    // If post_residual is small (e.g., < 10), it's dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Harmonic Fragmentation: Penalize based on the modulo of capacity.
    // Aim for "tight" bins by penalizing residuals that are not multiples of common item sizes.
    score += (post_residual % 10) as f64 * 1.5;

    // 5. Global Efficiency: If we are near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 6. New Bin Threshold: If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We only want to open a new bin if the fitting_bins_count is low or the current fit is terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 10.0; // Force open new bin if nothing else fits
        } else {
            // Heavily penalize opening a new bin if existing bins can fit the item
            score = 100.0 + (mean_residual * 0.5);
        }
    } else {
        // Encourage using existing bins that have a residual similar to the mean residual
        // to maintain uniform bin states.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the remaining space (Best Fit approach)
    let mut score = post;

    // Penalty for creating "fragmentation" (small, unusable residues)
    // We penalize post_residual values that are smaller than the smallest likely items (e.g., < 10)
    // but only if we are not near the end of the stream.
    if post < 10.0 && post > 0.0 {
        score += (10.0 - post) * 5.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, we penalize this bin for being unable to take the next item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 2.5;
    }

    // Dynamic thresholding for opening new bins:
    // If residual == cap, we are evaluating a brand new bin.
    // We only open a new bin if the current 'best' fit is very poor (high post_residual).
    if residual == cap {
        // If there are no other bins that can fit the item, we must open a new one.
        if fitting_bins_count == 0 {
            score = -100.0; // Force selection
        } else {
            // Otherwise, opening a new bin is expensive.
            // We scale the cost of a new bin by the progress; as we reach the end,
            // we become more conservative about opening new bins.
            score = 15.0 + (progress * 50.0);
        }
    } else {
        // Reward bins that bring the mean residual closer to the ideal (which is 0).
        // This encourages filling bins tightly.
        score += (post - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // Already in 'score', we reward smaller post_residual.

    // 2. Lookahead Synergy: If next item fits in the remaining space, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are too small to fit common items 
