    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 45.0; // Penalty for creating a "dead" residual
        }
        // Reward residuals that are perfect multiples or leave room for common item sizes
        if post_residual % 25 == 0 { score -= 15.0; }
