    let mut score = post;

    // Favor bins that leave a residual capable of fitting the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - progress);
        } else {
            // Penalize creating "dead zones" that cannot fit likely upcoming items
            score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive 
    // about filling bins tightly to avoid opening new ones late in the process.
    if bin_residual == bin_capacity {
        // New bin penalty: increases as we approach the end of the stream
        score += 40.0 + (30.0 * progress);

        // If we have many open bins, penalize opening another one
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If this is the only bin that can fit the item, prioritize it highly
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Reward bins that bring the residual closer to the mean residual of existing bins
        // This encourages "clustering" of similar bin states
        let diff = (post - mean_residual).abs();
        score += diff * 0.5;
    }

    // Non-linear coupling: penalize very small residuals (fragmentation) 
    // unless they are zero (perfect fit)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Class Penalty: Penalize residuals that are not multiples of common item sizes (e.g., 20, 25)
    // This targets "dead space" that cannot accommodate standard divisors of 100.
    let harmonic_penalty = ((post_residual % 20) as f64) * 1.5;
    score += harmonic_penalty;

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can still fit it (post_residual >= next_item_size)
    if next_item_size > 0 {
        if post_residual < next_item_size {
