    // 3. Density Balancing: If open_bins_count is high, prioritize closing gaps (Best Fit)
    // If open_bins_count is low, be more lenient to avoid opening new bins too early.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0; // Strong incentive to use the last fitting bin
    }

    // 4. New Bin Thresholding: Penalize opening a new bin unless the residual is very poor
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we are forced to (penalty is high if we have room in existing bins)
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range (0, 10), it is likely to become 
    // unusable given the item size range (10-80). Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the current number of open bins and the progress of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (open_bins_count as f64 * 0.5) + (progress * 20.0);
    }

