            score -= 25.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // incentivize picking it to prevent wasting a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Residual Balancing: Penalize bins that deviate too far from the average 
    // fullness, promoting a uniform distribution of residuals.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
