            score += 20.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: Near the end of the stream, prioritize packing tightly
    // to minimize the need for final bins.
    let density_pressure = (open_bins_count as f64 * bin_capacity as f64) / (step_index + 1) as f64;
    score += density_pressure * progress * 5.0;

    // Discourage opening a new bin unless the fit is extremely poor in all existing bins
    if bin_residual == bin_capacity {
