pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (standard BF behavior).
    // 2. Lookahead Synergy: If the post_residual is close to the next_item_size, reward it.
    //    We subtract a bonus if the post_residual can accommodate the next item (tight packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for perfect or near-perfect fit for the lookahead item.
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalty if the lookahead item cannot fit in this bin anymore.
            score += 20.0;
        }
    }

    // 3. New Bin Threshold: If this is an empty bin (new bin candidate).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full).
        // If mean_residual is high, we should force usage of existing bins.
        score += mean_residual * 0.8;

        // If there are many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 15.0;
    }

    // 4. Density Balancing: Avoid creating bins that are slightly below mean_residual.
    // If the post_residual is significantly better than the current average, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer the smallest post-residual (Best Fit logic).
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (residuals < 10 are often unusable for the given range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item fits into the current post-residual, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
