        if fitting_bins_count > 0 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Balance against mean residual: Avoid deviating too far from the average state of open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // End-of-stream adjustment: Become more aggressive with Best Fit as we approach the end.
    if progress > 0.9 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish high post_residual (Best Fit principle)
    // We want to minimize post_residual to keep space tight.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: 
    // Scale the penalty by the progress; early on, be conservative.
    // Late in the stream, favor opening a new bin if it avoids leaving bad fragments.
    if is_new_bin {
        score += 25.0 + (progress * 15.0);
    }

    // Lookahead logic: if next_item_size exists, penalize configurations that 
    // leave a post_residual that is too small for the next item (dead space).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Coupling: If we have many open bins, we should be more aggressive 
    // about filling existing ones rather than opening new ones.
    if open_bins_count > 0 {
        let density_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score -= density_factor * 10.0;
    }

    // Critical constraint: If this is the only bin that fits the item, 
    // heavily prioritize it to avoid unnecessary new bin creation.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Non-linear interaction: punish creating bins that are very empty 
    // when we are near the end of the stream.
    if !is_new_bin {
        score += (post_residual as f64).powf(1.1) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. 
    // New bin candidate is recognized when bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Base cost: The tighter the fit, the better (Best-Fit principle).
    let mut score = post_residual as f64;

    // 2. Harmonic Penalty: Penalize gaps that are unusable for common item sizes.
    // Small gaps (1-9) are often "dead space" unless they perfectly match an item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Reward perfect packing for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 4. Harmonic thresholding: Favor bins that leave room for items around 25, 33, or 50.
    // These represent 1/4, 1/3, and 1/2 of the bin capacity.
    if post_residual > 0 {
        let harmonic_fit = (post_residual % 25 == 0) as i32 * 5 + (post_residual % 33 == 0) as i32 * 4;
        score -= harmonic_fit as f64;
    }

    // 5. New Bin Management: 
    // Only open a new bin if the fitting bins are "too full" or "too empty" to accommodate future items.
    if is_new_bin {
        // Penalize opening a new bin heavily unless we have very few options.
        score += 40.0;

        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // If this bin is the ONLY one that fits the item, reward it to prevent wasting space elsewhere.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Global efficiency: Favor bins that stay near the mean residual of the set.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": gaps smaller than the minimum possible future item (assume 10).
    // If a bin has a post-residual < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open bins pressure: If many bins are open, we want to consolidate.
    // Increase cost of new bins or bins that result in high post-residuals.
    score += (open_bins_count as f64) * 0.5;

    // 3. Lookahead synergy: If the next item fits into the current post-residual, 
    // reward this placement (making the bin score lower).
    if next_item_size > 0 && post_residual >= next_item_size {
