        score += 30.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 5. Balance with mean residual: Avoid creating bins that are significantly 
    // worse than the current average state of the system.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin:
    // If this is a new bin (residual == capacity), penalize it based on how many
    // existing bins could have taken the item.
    if bin_residual == bin_capacity {
        score += 45.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 2. Lookahead matching:
    // If the post_residual is close to the next_item_size, we reward this bin.
    // We prefer post_residual >= next_item_size to avoid forcing a new bin later.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward: minimize gap between post_residual and next_item_size
            score -= (100.0 - (post_residual as f64 - next_item_size as f64));
        } else {
            // Penalty for creating a bin that cannot accommodate the next item
            score += 30.0;
        }
    }

    // 3. Density balancing:
    // If current bin's post_residual is significantly lower than the mean_residual
    // of other bins, it's a "tight" bin. We want to pack tight bins tightly.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. Progress-based scaling:
    // As the stream nears completion, become more aggressive about filling existing bins
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    // 5. Final constraint:
    // Heavily penalize placements that result in tiny, unusable slivers (e.g., < 5)
    // unless it's a perfect 0-residual fit.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
