pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res = bin_residual as f64;

    // Core objective: Minimize post_residual, but penalize "fragmentation" 
    // that leaves residual space too small to fit typical future items.
    // We use a non-linear penalty for tight bins (post_residual < 10) 
    // to avoid creating unusable slivers, especially late in the stream.
    let fragmentation_penalty = if post_res < 10.0 && post_res > 0.0 {
        (10.0 - post_res).powi(2) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that align with the mean residual to keep bin levels balanced.
    // This prevents creating "outlier" bins that are nearly full while others are nearly empty.
    let balance_penalty = (res - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, favor bins that have enough space
    // to accommodate it (i.e., post_residual >= next_item_size).
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Bias against opening new bins early (progress < 0.8) by penalizing the new bin candidate.
    // The new bin candidate has bin_residual == bin_capacity.
    let new_bin_bias = if bin_residual == bin_capacity {
        (1.0 - progress) * 50.0 + 20.0
    } else {
        0.0
    };

    // Final score: prioritize tight fits (low post_residual) while smoothing with penalties.
    post_res + fragmentation_penalty + balance_penalty + lookahead_penalty + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
