    }

    // 5. Global Load Balancing: Adjust based on mean_residual.
    // If the mean residual is high, we are being too loose; tighten up.
    if mean_residual > 30.0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Progression Scaling: Be more aggressive as the stream nears completion.
    let progress = step_index as f64 / total_items as f64;
