    // Favor bins that bring the mean residual closer to the target (e.g., 20% of capacity)
    let mean_alignment = (post - (mean_residual * 0.8)).abs();

    // Bias against opening new bins early in the stream; favor existing open bins
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
