    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin
            score = -1000.0;
        } else {
            // Only open if the existing fits are all "bad" (e.g., leave tiny fragments)
            // or if we have plenty of open bins already.
            score += 60.0 + (open_bins_count as f64 * 2.0);
            if progress > 0.9 {
                score -= 20.0;
            }
        }
    } else {
        // If this is the last chance for this item (fitting_bins_count == 1), 
        // heavily reward placing it here to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Penalize bins that deviate too far from the mean residual to keep bin fill levels balanced.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base score: punish large post-residuals to encourage Best Fit (packing tightly)
    let mut score = post.powi(2) / cap;

    // Penalty for creating a "small hole" (unusable space < 10)
    // Small holes are catastrophic for later items (10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: if next item is large, favor bins that can accommodate it
    // If next_item_size is 0, we are at the end, so prioritize closing bins
    if next_item_size > 0 {
        let fit_penalty = if post_residual < next_item_size { 25.0 } else { 0.0 };
        score += fit_penalty * (1.0 - progress);
    }

    // Progression coupling: towards the end of the stream, prioritize minimizing total open bins
    // by penalizing the creation of new bins (represented by bin_residual == cap)
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress);
    }

    // Pressure normalization: if many bins are open, push to fill existing ones more aggressively
    // by penalizing the post-residual more heavily as open_bins_count increases
    score += (open_bins_count as f64) * (post / cap) * 5.0;

    // Favor bins that align with the global mean residual to keep bin states uniform
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // Goal: Minimize post_residual while avoiding "fragmentation traps" (small remainders that cannot fit future items).
    // We penalize post_residual values that are likely to be wasted (small values < 10).
    // We reward placements that leave space compatible with the next_item_size.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: If post_residual is small (1..9), it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Alignment: Reward post_residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "harmonic" bin states that are more likely to accept future items.
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    // 3. Lookahead Synergy: If post_residual perfectly accommodates next_item_size, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual < (next_item_size + 10) {
            // Reward "tight" fits for the upcoming item.
            score -= 15.0;
        }
    }

    // 4. New Bin Thresholding: 
    // If bin_residual == bin_capacity, it's a new bin. 
    // We only open a new bin if the current open bins are "poor" (mean_residual is low).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // New bin is expensive, penalize unless existing bins are already very full.
            score += 60.0;
        } else {
            // Otherwise, keep the score neutral/competitive.
            score += 30.0;
        }
    }

    // 5. Urgency: If fitting_bins_count is 1, we are at the limit of our options.
    // Discourage wasting the last fitting bin if it creates a tiny fragment.
    if fitting_bins_count == 1 && post_residual < 10 {
        score += 15.0;
    }

    // 6. Progress Scaling: As the stream progresses, prioritize filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
