    // proportional to the current progress to discourage opening new bins late in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (15.0 + (progress * 40.0)) * (1.0 + open_bins_count as f64 * 0.1) 
    } else { 
        0.0 
    };

    // Calculate a "tightness" penalty: we prefer post_residual to be small (Best Fit),
    // but not so small that it leaves unusable "dead space" (e.g., < 10 units) 
    // unless the item is a perfect fit (post_residual == 0).
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        12.0 - (post_residual as f64 * 0.5)
    } else {
        0.0
    };

    // Use lookahead to discourage placing items that create poor residuals for the next item.
    // If next_item_size exists, we penalize bins that cannot fit the next item after this one.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        8.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Normalize score based on mean_residual to favor bins that are already "fuller" than average.
    let fullness_adjustment = (post_res - mean_residual) * 0.2;

    // Combine into a non-linear score.
    // We aim to minimize this value.
    let score = post_res 
        + new_bin_penalty 
        + dead_space_penalty 
        + lookahead_penalty 
        + fullness_adjustment;

    score
}

