    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We apply a non-linear penalty for creating "dead zones" (small residuals) 
    // that are unlikely to accommodate future items.
    let mut score = post;

    // Penalty for creating a new bin:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on progress.
    // Early in the stream, we are more conservative; late in the stream, we are more aggressive.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * (1.0 - 0.5 * progress) * (1.0 + (fitting_bins_count as f64).powf(0.5));
    } else {
        // Reward placements that align with the mean residual to keep bin levels balanced.
        let deviation = (post - mean_residual).abs();
        score += 0.2 * deviation;

