    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0 * (1.0 - progress);
        } else {
            // Reward bins that maintain enough space for the next item
            score -= 20.0 * (1.0 - progress);
        }
    }

    // Encourage filling bins that are already "tight" to maximize density
    // by comparing current post_residual to the global mean_residual.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // If this is the only fitting bin, prioritize it to avoid wasting a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Discourage opening new bins early in the process unless necessary
    if bin_residual == bin_capacity {
        score += 35.0 + (25.0 * progress);
    }

    // Penalize bins that deviate heavily from the average state of open bins
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Minimizing this naturally pushes towards Best-Fit (filling bins tightly).
    let mut score = post_res;

    // Penalty for creating "fragmented" space (small, unusable residuals).
    // If post_residual is in the range (0, 10), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item cannot fit into the current post-placement residual,
    // penalize the choice proportional to how much the next item "needs" that space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res) * 0.5;
    }

    // Dynamic threshold: As the stream progresses, prioritize closing bins (lower residual) 
    // to keep the bin count tight.
    score += (progress * 15.0) * (post_res / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // based on how many bins are already available to accept the item.
    // This forces the heuristic to use existing bins unless they are extremely poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64 * 5.0);
    }

    // Adjust score based on global mean_residual. 
    // If the current bin's post_residual is significantly worse than the average, penalize it.
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
