    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress and open bin pressure.
    // We want to avoid opening new bins unless the fit is exceptionally poor in existing ones.
    if is_new_bin {
        score += 15.0 + (open_bins_count as f64 * 2.5) + (progress * 10.0);
    } else {
        // Harmonic Logic: Favor post_residuals that are multiples of common item sizes (e.g., 20, 25)
        // or residuals that are very small (leaving little wasted space).
        let wasted = post_residual as f64;

        // Penalty for "dead zones" (e.g., residual 1-9 is often unusable for large items)
