                score -= (100.0 / (1.0 + (post_residual as f64 - space_needed_for_next).abs()));
            }
        }
    }

    // Adjust score based on how many other bins could fit this item.
    // If fitting_bins_count is high, we are less desperate to pick a specific bin.
    if fitting_bins_count > 1 && !is_new_bin {
        score += (fitting_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
