    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing bin could fit
            score += 150.0;
        } else {
            score -= 10.0; // Preference to open if no other choice
        }
    }

    // 3. Lookahead Logic: If current bin can fit the next item, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that create a perfect or near-perfect fit for the next item
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= (50.0 - lookahead_fit).max(0.0) * 1.5;
    }

    // 4. Global balance: If we have many open bins, penalize leaving large residuals
    // This pushes the algorithm to fill existing bins rather than spreading items thin
    if open_bins_count > 5 {
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;
    }

    // 5. Criticality: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Density check: Penalize creating "dead zones" (residuals < 10) that are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
