        let gap_penalty = if post_residual < 10 && post_residual > 0 {
            50.0 / (post_residual as f64 + 0.1)
        } else {
            0.0
        };

        let mut s = post_residual as f64 + gap_penalty;

        // Lookahead coupling: if next item is large, favor bins with more space
        if next_item_size > 0 {
            let space_for_next = post_residual as f64 - next_item_size as f64;
            if space_for_next < 0.0 {
                // If this bin cannot fit the next item, add a penalty proportional to the next item's size
                s += (next_item_size as f64 * 0.8) * (1.0 - progress);
            }
        }

        // Interaction with mean_residual: avoid deviating too far from the average bin utilization
        let deviation = (post_residual as f64 - mean_residual).abs();
        s += deviation * 0.2;

        s
    };

    // If this is the last fitting bin, grant a slight bonus to avoid opening a new one unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large residuals directly.
    // 2. Harmonic penalty: heavily penalize tiny residuals (e.g., 1-5) that are 
    //    likely to become "orphaned" space (cannot fit any item).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 3. Lookahead synergy: if next_item_size fits in the post_residual, 
    //    reward this bin heavily to keep it alive.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Thresholding: Avoid opening new bins unless necessary.
    //    If this is a new bin (residual == capacity), add a high base cost 
    //    unless it's the only option.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly 
    //    from the average state of the system to encourage uniform filling.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 6. Harmonic class pressure: Favor filling bins to near-capacity (90-99 range).
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // 7. Contextual density: If few bins can fit the current item, 
    //    prioritize preserving the most capable bins.
    if fitting_bins_count < 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": post_residuals between 1 and 9 are extremely hard to fill.
    // We apply a non-linear penalty for creating such gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If the next item is large, prioritize bins that can fit it.
    // If the next item won't fit in the remaining space, we slightly penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Open bins pressure: If we are near the end of the stream, prioritize closing bins
    // (lowering open_bins_count). If we are early, prioritize bin density.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // 4. New bin penalty: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the existing options are very poor.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is scaled by how many bins are already open.
        score += 40.0 + (open_bins_count as f64 * 5.0);
    }

    // 5. Fitting count awareness: If this is the only bin that can fit the item, 
    // we should favor it to avoid the high cost of a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Balance residual: Favor bins that stay close to the mean residual to keep
    // bin levels uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals smaller than the smallest likely item, 10).
