        // and inversely proportional to the mean residual (if we have lots of space, don't open new ones).
        score = 40.0 + (progress * 20.0) + (mean_residual * 0.5);
    } else {
        // Best-Fit Decreasing logic: favor bins that result in small residuals.
        // Penalty for creating a "fragment" that is too small for any likely item (e.g., < 10).
        if post_residual > 0 && post_residual < 10 {
