        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (1-9 range) non-linearly
    let gap_penalty = if post_residual < 10 {
        (10.0 - post_res).powi(3) * 5.0
    } else {
        0.0
    };

    // Favor bins that fit the next item (Lookahead anticipation)
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (next_item_size as f64 / 100.0)
    } else {
        0.0
    };

    // Encourage filling bins deeper as the stream progresses
    // At the start, be conservative; near the end, be aggressive to clear bins
    let progress_weight = 20.0 * (1.0 - progress);

    // Normalize residual impact based on remaining bin space
    // We want to minimize post_residual, but prioritize filling bins that are already partially full
    let base_score = post_res + (progress_weight * (post_res / bin_capacity as f64));

    // If only one bin fits, we are forced to take it unless it's a terrible fit
    // Penalize opening a new bin (where bin_residual == bin_capacity) heavily unless necessary
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 { 50.0 } else { 0.0 }
    } else {
        0.0
    };

    base_score + gap_penalty + lookahead_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
