    // We penalize larger post_residuals heavily.
    score += post_residual as f64 * 1.5;

    // 2. "Last-Chance" Logic: If this is the only bin that fits the current item, 
    // prioritize it strongly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
