    // to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Non-linear coupling: penalize very small residuals (dead space) 
    // more aggressively as the stream progresses.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 + progress);
