        // If we are late in the stream, be more conservative about opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Reward existing bins that keep the mean residual balanced
        if (post_residual as f64) < mean_residual {
