    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If the bin is new (bin_residual == bin_capacity), add a threshold cost.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual,
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Global Efficiency: Penalize excessive open bins relative to the mean residual
    // to encourage packing items into tighter, existing clusters.
    score += (open_bins_count as f64) * (100.0 - mean_residual) * 0.1;

    // 6. Progress Scaling: As the stream nears completion, become more aggressive
    // about closing gaps to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

