pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: 0 means a perfect fit (highly desirable).
    // Small post_residual is usually good, but very small (e.g., 1-5) often creates "dead space".

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "dead space" (tiny residual that is hard to fill).
    // If post_residual is small but > 0, increase score to discourage it.
    if post_residual > 0 && post_residual < 10 {
