    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // If we are considering a new bin (bin_residual == bin_capacity):
    // Only open if we have many bins already or if the item is large (>= 70).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Apply a high cost to opening a new bin unless item is very large or 
            // current strategy is failing (high mean_residual).
            score += 50.0 + (mean_residual * 0.5) + (progress * 20.0);
            if item_size > 70 {
                score -= 30.0;
            }
        }
    }

    // Encourage keeping bins balanced by penalizing bins that deviate significantly
    // from the mean_residual of other open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
