            score += 65.0 - (mean_residual * 0.5);
        }
    }

    // 4. Harmonic Alignment: Reward fitting into bins that align with the mean usage.
    // This helps keep bins packed at similar densities.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Progression Weighting: As the stream nears completion, become more aggressive
    // about utilizing the current open bins to prevent stranded space.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

