    // 4. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the open bins are already very full (high mean_residual makes it easier to open new bins).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
