    score += dev * 0.1;

    // 6. Progression scaling: As we reach the end of the stream, prioritize closing open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (< 10) 
    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // 3. Global State Balancing: If we have many open bins, penalize opening a new one.
    // If we have few, be more aggressive to pack items tightly.
    if is_new_bin {
        score += 25.0 * (open_bins_count as f64 / (1.0 + (progress * 10.0)));
    } else {
        // Encourage using existing bins that are close to the mean residual to keep bins balanced.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, 
    // heavily bias towards it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Progression Bias: As we near the end of the stream, prioritize closing bins (lower residual).
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
