    // Penalty for creating a "dead zone": if the remaining space is too small to be useful
    // for future items (e.g., < 10), it is often better to have used a different bin.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_res * 5.0);
    }

    // Lookahead logic: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Pressure mechanism: If we have many open bins, penalize opening a new one 
    // to force consolidation.
    if is_new_bin {
        score += (open_bins_count as f64) * 15.0;

        // If there are other bins that could fit this item, strongly discourage opening a new one
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Reward bins that bring the mean residual closer to the ideal (half capacity)
    // to maintain flexibility for incoming items.
    let target_mean = bin_capacity as f64 * 0.5;
    let current_mean_diff = (mean_residual - target_mean).abs();
    score += current_mean_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If post_residual can fit the next item, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
        // Further reward if it's a tight fit for the lookahead item
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. New Bin Penalty: If this is a new bin, apply a significant barrier.
    // Only open a new bin if the existing options are truly poor (e.g., leaving large gaps).
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 4. Scarcity Logic: If this is the last fitting bin, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Balance: If the current bin is significantly worse than the mean, penalize it.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 6. Progression Weighting: As the stream nears the end, become more aggressive about consolidation.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
