    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We want to minimize post_residual, so it acts as a primary component.
    let mut score = post;

    // Penalty for creating a "fragmented" bin:
    // If post_residual is small but > 0, it is often worse than 0 (exact fit).
    // If post_residual is in the "danger zone" (e.g., < 10), we penalize it 
    // because it's unlikely to fit future items.
    if post > 0.0 && post < 15.0 {
        score += 25.0 * (1.0 - (post / 15.0));
    }

    // Lookahead coupling:
    // If we have a next_item, we want to ensure the post_residual is large enough to accommodate it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Strong penalty for blocking the next item from this bin
            score += 50.0 * (1.0 - progress.powf(0.5));
        }
