        // Lookahead heuristic: If the next item can fit in this bin, favor this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 * (1.0 - progress);
        }

        // If this is the last chance to fit the item in an existing bin, reduce penalty
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Adjust for global state: if we have too many open bins, prioritize closing them
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that cannot fit common small items (e.g., < 20).
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 20 {
        score += 35.0 - (post_residual as f64 * 1.5);
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // highly reward this bin (Best Fit Decreasing logic).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // Harmonic class logic: Favor bins that leave remainders which are multiples of 
    // likely item sizes (e.g., 25, 33, 50).
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // If this is the only bin that fits, we are forced to take it, but we should 
    // prioritize the one that leaves the best residual for future items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New bin aversion: If we are opening a new bin (bin_residual == bin_capacity),
    // only do so if the current open bins are all very tight (high penalty).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is very small.
        if mean_residual > 15.0 {
            score += 50.0; 
        } else {
            score += 5.0;
        }
    }

    // Normalize by progress: Towards the end of the stream, prioritize closing 
    // bins (lower post_residual) over creating new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residuals that are too small to fit any likely subsequent items.
    // If a gap is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item cannot fit in the current post_residual,
    // we penalize the bin slightly to favor bins that leave room for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 3. Open bin pressure: Penalize opening new bins when existing bins have capacity.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already (high pressure)
        // or if fitting_bins_count is zero (forced).
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Tightness reward: Favor bins that are already "fuller" (lower mean_residual)
        // to keep the distribution of residuals consistent.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 5. Progression scaling: As we reach the end of the stream, prioritize finishing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead: Reward placements that fit the next item perfectly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // 3. Penalty for opening new bins prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // Penalize opening a new bin if we are near the end of the stream
        score += 20.0 * (step_index as f64 / total_items as f64);
    }

    // 4. Balance: Favor bins that stay close to the current mean residual
    // This helps maintain a uniform packing density
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Efficiency: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. 
    // Lower residual is generally better (Best-Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too sparse (fragmentation)
    // We penalize high post_residual values, especially if we are late in the stream.
    score += (post_residual as f64).powf(1.2) * (0.5 + 0.5 * progress);

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // we should prioritize this bin significantly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // If this is the only bin that can fit the item, we should be careful 
    // about opening a new bin instead.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New bin management: Opening a new bin is expensive.
    // We only open a new bin if the current existing bins are "too full" to be useful
    // or if the residual is extremely awkward.
    if is_new_bin {
        if open_bins_count == 0 {
            score = -100.0; // Always open the first bin
        } else {
            // Only open a new bin if the average residual of existing bins is very small,
            // meaning they are all nearly full and likely won't fit the next item.
            score += 40.0;
            score += mean_residual * 0.5;
            // Discourage opening new bins as the stream nears completion
            score += progress * 50.0;
        }
    }

    // Fine-tuning: Favor bins that maintain a residual close to the mean, 
    // discouraging outlier bins that create dead space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual).
    // We add a penalty for creating "dead zones" (small residuals that are unlikely to fit future items).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (post_residual > 30)
    // or if we are early in the stream and need to keep bins consolidated.
    if is_new_bin {
        score += 35.0 + (progress * 20.0);
        // If there are other bins that could fit the item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Reward bins that bring the residual closer to the mean residual of other bins (load balancing).
        let imbalance = (post_residual as f64 - mean_residual).abs();
        score += imbalance * 0.2;

        // Lookahead heuristic: If the next item is large, avoid leaving a tiny residual in this bin.
        if next_item_size > 0 {
            let next_fit_penalty = if post_residual < next_item_size { 15.0 } else { 0.0 };
            score += next_fit_penalty * (1.0 - progress);
        }
    }

    // Non-linear coupling: penalize very small residuals (e.g., 1-5) as they are hard to fill,
    // unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 6 {
        score += 10.0 * (1.0 - (post_residual as f64 / 6.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residuals (tight packing)
    // 2. Penalty for creating "dead space": small residues that cannot fit common items (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: if the next item fits into the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic coupling: avoid leaving residual space that is a poor fraction of capacity
    // Penalize residues that are roughly 1/2 or 1/3 of capacity if they don't accommodate next_item
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio > 0.4 && residual_ratio < 0.6 {
        score += 15.0;
    }

    // 5. Thresholding: if this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 6. New bin penalty: discourage opening new bins unless the fit is extremely tight (Best-Fit)
    if bin_residual == bin_capacity {
        // Only open new if we have many open bins already or if the item is large
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 7. Stream progression scaling: become more conservative as we approach the end
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items (10-20)
    // but too large to be considered "full".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins unless the current options are very poor.
    // If this is a new bin (bin_residual == bin_capacity), add a cost proportional to existing open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, give it a significant bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Global Efficiency: If the bin is becoming too empty compared to the mean, penalize it to encourage
    // consolidation, unless it's a new bin.
    if bin_residual != bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Basic Best-Fit strategy: prioritize minimizing post_residual (the space left in the bin).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely: 
    // If this is an empty bin (new bin candidate), apply a heavy penalty unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0; // Discourage opening a new bin if we can fit it elsewhere
        }
    }

    // Aggressive Lookahead: If we know the next item, we want to maximize the chance that 
    // the post_residual can accommodate the next_item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly (leave little waste)
            let waste_after_next = (post_residual - next_item_size) as f64;
            score -= (50.0 - waste_after_next).max(0.0);
        } else {
            // Penalize bins that would leave a "dead zone" too small for the next item
            score += 15.0;
        }
    }

    // Global context: If mean_residual is high, we are being too sparse. 
    // Force tighter packing by penalizing high post_residual values more heavily.
    if mean_residual > 30.0 {
        score += post_residual as f64 * 0.5;
    }

    // Favor filling bins that are already "half-full" to keep the number of active bins low.
    let current_fill = bin_capacity - bin_residual;
    if current_fill > 40 {
        score -= 10.0;
    }

    // Final adjustment based on proximity to the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the remaining space. Smaller post_residual is generally better (Best Fit).
    // post_residual == 0 is the ideal target.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that are unlikely to fit future items).
    // If the post_residual is too small to fit the smallest possible items (assumed ~10), it is a dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead logic: If the next item cannot fit in this bin, penalize the placement.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Global state awareness: If we have many open bins, prioritize tightening existing ones.
    // If we have very few open bins, we can be more lenient to keep options open.
    score += (open_bins_count as f64) * 0.5;

    // 4. Dynamic time horizon: As we approach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 5. Handling the "New Bin" candidate (bin_residual == bin_capacity).
    // If this is a new bin, penalize it relative to fitting into an existing one.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist.
            score += 40.0;
        } else {
            // If no other options exist, this is the only choice.
            score -= 10.0;
        }
    }

    // 6. Reward bins that align with the global mean residual to keep bin states uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny slivers (dead space) that are hard to fill later
    // We prioritize bins that leave exactly 0 space or enough space for common item sizes
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        15.0 * (1.0 - post / 10.0)
    } else {
        0.0
    };

    // Use next_item_size to favor bins that can accommodate the upcoming item
    // If next_item_size fits in the post_residual, reward this bin
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -12.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Influence of open_bins_count: as we near the end of the stream (progress -> 1),
    // we want to be more aggressive about packing tightly to close bins.
    let packing_efficiency = (post / bin_capacity as f64) * (1.0 + progress);

    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // If we choose a new bin instead, we pay a heavy penalty.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 { 40.0 * (1.0 - progress) } else { 0.0 }
    } else {
        0.0
    };

    // Combine terms: 
    // - Base score is the post_residual (Best Fit principle)
    // - Apply non-linear penalties for dead space and lack of lookahead synergy
    // - Reward higher packing efficiency as the stream progresses
    let score = post 
        + dead_space_penalty 
        + lookahead_bonus 
        + (packing_efficiency * 10.0)
        + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic Best-Fit with Lookahead Pressure
    // Objective: Minimize post_residual, but heavily penalize small fragments that cannot fit future items.

    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is smaller than the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Encourage filling bins to capacity (harmonic weighting)
    // We reward bins that approach the harmonic threshold of the capacity
    let fill_ratio = (bin_capacity - bin_residual + item_size) as f64 / bin_capacity as f64;
    score -= (fill_ratio * 20.0);

    // If this is the only bin that can fit the item, prioritize it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // Discourage opening a new bin unless the current fill efficiency is poor
    if bin_residual == bin_capacity {
        // Base cost for a new bin is high, but scales down if existing bins are very full
        score = 45.0 + (mean_residual * 0.5);

        // If we are near the end of the stream, penalize opening new bins heavily
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // Harmonic class logic: penalize post_residuals that sit in 'awkward' ranges
    // (e.g., leaving 1-9 space is usually worse than leaving 0)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

