    // lower the score to prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Fragmentation Control: Penalize opening new bins if there are already many open.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If we have other bins that can fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 60.0;
