        // Reward using existing bins, specifically those that are getting "full" (closer to 0 residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Progression Scaling: As we near the end of the stream, discourage new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize keeping the residual as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, reward this bin.
    // This effectively implements a Best-Fit-Decreasing-like logic for the next step.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 2.5;
        } else {
            // Penalize creating a bin that is too small for the next item
            score += (next_item_size as f64) * 0.8;
        }
    }

    // 3. New Bin Threshold: Discourage opening a new bin unless existing bins are very poor fits.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the mean residual of existing bins is already tight (< 15)
        // or if there are no bins that can fit the current item effectively.
        if mean_residual > 20.0 || fitting_bins_count > 0 {
            score += 80.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize creating more.
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 5. Fragmentation Avoidance: If this bin is the last chance for the current item,
    // give it a slight preference to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
