    } else {
        // Reward tight fits that leave little room for waste
        // We punish large post_residuals more as the stream nears completion
        score += (post_residual as f64).powf(1.1) * (1.0 + progress);

        // Lookahead: If next_item_size is large, favor bins that can accommodate it.
        // If the current post_residual is smaller than the next item, we create 'dead space'.
