            }
        }

        // If this is the last chance to fit an item into an existing bin, reduce the penalty
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Dynamic thresholding: as we near the end of the stream, prioritize packing 
    // existing bins tighter to avoid stragglers.
    score += (1.0 - progress) * (open_bins_count as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream ends.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 80.0 + 20.0
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: heavily favor bins that leave the smallest residual (Best Fit).
    // The exponent 1.5 creates a non-linear penalty for larger remaining gaps.
    let fit_score = post.powf(1.5);

    // Lookahead coupling: If next_item_size is large, penalize small post_residual values
    // that would result in a "fragmented" bin unable to fit the next item.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Use mean_residual to balance distribution: if this bin's post_residual is much 
    // smaller than the average, it's a "tight" fit, which is generally good.
    let balance_factor = if post < mean_residual {
