    // Progression awareness: shift strategy as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Tighten packing in late stages
        score += post_residual as f64 * 0.5;
    } else {
        // Early stages: prefer keeping mean_residual balanced
        if (post_residual as f64) < mean_residual {
