        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: If the next item could fit in this post-residual, 
    // prioritize this bin to increase packing density.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 15.0 * (next_item_size as f64 / 100.0);
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, become increasingly conservative about opening new bins.
    // If we are late in the stream, heavily penalize opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 35.0 * progress;

        // If there are other bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Coupling with global state: 
    // If the current bin's residual is significantly larger than the mean residual, 
    // penalize it to encourage filling the tighter bins first (balancing).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small for common items (below 10).
    // We heavily penalize residuals that are not zero and are smaller than the smallest likely item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Lookahead logic: if next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a perfect fit for the next item.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that block the next item from fitting.
            score += 15.0;
        }
    }

    // Harmonic class logic: favor filling bins to specific fractions (1/2, 1/3, 1/4 of capacity).
    // This clusters items into bins with similar residual characteristics.
    let harmonic_penalty = ((post_residual % 25) as f64).powf(1.2);
    score += harmonic_penalty;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy "opening cost"
    // to force the algorithm to prefer existing open bins unless the fit is truly terrible.
    if bin_residual == bin_capacity {
        score += 45.0;

        // Dynamically adjust new bin cost based on how many bins are already open.
        // As open_bins_count increases, we become more reluctant to open another.
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid wasting space elsewhere.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Normalize against mean_residual to prevent massive variance in bin filling.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it is highly likely to be wasted.
    // We penalize this heavily because items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is perfect or necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty unless 
    // it's the only option or the current open bins are already very full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0;
            // Scale penalty by progress: later in the stream, we are more desperate to avoid new bins.
            score += (step_index as f64 / total_items as f64) * 20.0;
        }
    } else {
        // 4. Tight Fit Reward: Favor bins that become very full (Best Fit behavior).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the average fullness.
    let current_bin_fullness = bin_capacity - bin_residual;
    let deviation = (current_bin_fullness as f64 - (bin_capacity as f64 - mean_residual)).abs();
    score += deviation * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin unnecessarily
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin can fit the item
            score += 150.0 + (mean_residual * 2.0);
        } else {
            // If no bins fit, base cost is the capacity minus item, slightly adjusted
            score = 50.0 - (item_size as f64 * 0.5);
        }
        return score;
    }

    // 2. Best-Fit logic: prioritize bins where post_residual is minimized
    // We favor tight fits that leave little room (minimizing dead space).
    score = post_residual as f64;

    // 3. Lookahead Logic: If next_item_size fits in the post_residual, reward this bin.
    // This is the core of the 2-step lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Mean Residual balancing: avoid creating bins that deviate significantly from the average.
    // If post_residual is much smaller than mean_residual, it is a "tight" bin.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Criticality: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 6. Progress adjustment: As the stream nears the end, prioritize closing bins (tighter packing).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to remaining stream length and how many bins are already open.
        // We only want to open a new bin if the current open bins are "too full" to handle future items efficiently.
        score = 45.0 + (open_bins_count as f64 * 0.5) + (progress * 10.0);
    } else {
        // Best-Fit Decreasing logic: penalize large post_residuals (wasted space).
        // Bias towards creating "perfect fits" (post_residual == 0).
        score = post_residual as f64 * 1.5;

        // If this is the last chance for this item, reward picking it strongly to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Lookahead: if the next item fits into the post_residual, reward this bin placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // Global state awareness: if the bin is already quite empty (high mean_residual), 
        // prefer filling it to keep the average bin usage high.
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 5.0;
        }

        // Late-stage optimization: as the stream ends, be more aggressive about filling existing bins.
        if progress > 0.8 {
            score -= (post_residual as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
