    let mut score = post_res;

    // Penalty for leaving "dead space": small residuals that are unlikely to fit future items.
    // We penalize residuals < 20 (the minimum item size) exponentially.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_res).powf(1.5) * 5.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // we strongly prefer this bin (rewarding tight packing).
    if next_item_size > 0 && post_residual >= next_item_size {
