    }

    // Coupling with open_bins_count: If we have many bins open, we penalize opening more
    // to encourage consolidating into existing bins.
    score += (open_bins_count as f64).powf(1.2);

    // If this is the last chance to fit the item in an existing bin, reduce the score
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Bias against very high mean_residual: If open bins are mostly empty, 
    // prefer filling those over creating new ones.
    score += mean_residual * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
