pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (small residuals that are unlikely to fit future items).
    // Specifically, penalize residuals < 20, as they are hard to fill given the 10-80 range.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Lookahead logic: If the next item is large, favor bins that can still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalty if we block a potential future placement for the next item
            score += 15.0 * (next_item_size as f64 / 100.0);
        }
    }

    // 3. Global state: If we have many open bins, penalize opening a new one significantly.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Exponential penalty for opening new bins when others are available
            score += 50.0 + (open_bins_count as f64 * 5.0) + (progress * 20.0);
        }
    } else {
        // 4. Tighten the fit: If it's the last chance (fitting_bins_count == 1), 
        // prioritize this bin to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Balance residuals: Avoid creating bins that deviate significantly from the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_r = post_residual as f64;

    // Base score: prioritize tighter fits (Best-Fit principle)
    let mut score = post_r;

    // Penalty for creating "dead zones": if post_residual is in the 1-9 range, 
    // it is highly unlikely to fit subsequent items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_r / 10.0));
    }

    // Lookahead logic: if the next item is large, prioritize bins that leave enough space for it.
    // We penalize bins that would be too small for the next item if we are mid-stream.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive 
    // about utilizing open bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New bin candidate: heavily penalize early in the stream, 
        // but allow if we have no good options.
        score += 40.0 + (30.0 * progress);

        // If we have many open bins, penalize opening a new one even further.
        score += open_bins_count as f64 * 2.0;
    } else {
        // Favor bins that align with the global mean to keep residual distribution uniform
        let deviation = (post_r - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // If this bin is the last chance for the current item, reduce penalty to ensure packing.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual)
    // We start with the base score = post_residual.

    // 2. Penalty for creating "Dead Zones":
    // If the post_residual is too small to fit common items (e.g., < 10), it is often wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Synergy (Harmonic coupling with next item):
    // If the next item fits into the current bin's post_residual, we reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Harmonic thresholding:
    // If we have many open bins, we want to consolidate. Penalize opening new bins unless
    // the current fit is exceptionally poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing one can accommodate the item.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, we must open a new one; normalize the cost.
            score = 50.0;
        }
    }

    // 5. Mean Residual balancing:
    // Avoid creating bins that deviate significantly from the mean residual of existing bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progressive packing (End-of-stream optimization):
    // As the stream nears completion (step_index / total_items -> 1.0), 
    // become more aggressive about filling existing bins to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it's likely unusable.
    // We penalize this heavily because items are at least 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is very good.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only prefer a new bin if the current open bins are very full (low mean_residual).
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 60.0; 
        } else {
            score += 20.0;
        }
    }

    // 4. Last Chance Logic: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Efficiency Bias: Favor bins that become "tight" (residual near 0).
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // If the bin is empty (new bin candidate), we penalize it based on how many bins are already open
    // to encourage filling existing bins first unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        return 150.0 + (open_bins_count as f64 * 0.5);
    }

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": if post_residual is between 1 and 9, 
    // it's likely to remain unusable given the item size distribution (min 10).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into the post_residual, 
    // prioritize this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward bins that leave exactly enough space for the next item
        score -= (100.0 - diff * 2.0);
    }

    // 3. Pressure to consolidate: If we are nearing the end of the stream, 
    // penalize opening new bins by making existing ones more attractive.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    // 4. Mean residual coupling: Penalize bins that deviate significantly from the mean 
    // residual of other open bins to keep bin levels balanced.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.3;

    // 5. Scarcity: If this is the only bin that can fit the item, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. Lower score = better fit.

