    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 3. Lookahead heuristic: If the next item fits into the post_residual, 
    // prioritize this bin heavily to maximize bin utilization.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Global state coupling: If we are near the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && fitting_bins_count > 0 {
        score -= (10.0 * progress);
    }

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Penalize opening a new bin unless the existing options are very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already very low,
        // or if fitting_bins_count is 0 (no other choice).
        if fitting_bins_count > 0 {
            score += 35.0;
        }

        // Add a cost based on how many bins are already open to discourage fragmentation.
        score += (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, favor those that bring the bin closer to the mean_residual
        // to keep bin levels balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is usually better (Best Fit).
    let mut score = post;

    // 1. Penalize creating "dead zones" (small residual space that cannot fit typical future items).
    // If post_residual is small but > 0, it's often worse than 0 (perfect fit).
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // 2. Lookahead coupling: If next_item_size is large, avoid bins that leave little space.
    // If the next item is 70+, we want to preserve larger residuals.
    if next_item_size > 60 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive about filling
    // existing bins versus opening new ones.
    // At the start, be conservative (prefer new bins). At the end, be greedy (fill everything).
    let new_bin_penalty = 15.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // 4. Entropy mitigation: Favor bins that align with the global mean residual to keep
    // the distribution of bin fillings uniform.
    let dev_from_mean = (post - mean_residual).abs();
    score += 0.2 * dev_from_mean;

    // 5. If this is the only bin that can fit the item, prioritize it heavily to avoid 
    // unnecessary bin creation, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize creating small, unusable residuals that are not multiples 
    // of common item sizes. We favor residuals that are 0 (perfect fit) or > 30 (flexible).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 / (post_residual as f64 + 1.0));
    }

    // 2. Lookahead Coupling: If next_item_size is large, avoid leaving a residual 
    // just slightly smaller than that item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > (next_item_size / 2) {
            score += 25.0;
        }
    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one 
    // unless the fit is exceptionally good (Best Fit logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item
            score += 60.0 + (fitting_bins_count as f64 * 10.0);
        }
    } else {
        // Reward bins that bring the mean residual closer to the target 
        // (trying to keep bins packed evenly).
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // 4. Progression Scaling: As the stream nears the end, prioritize tightest fit 
    // (minimize post_residual) to avoid stranding items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
