    // We want to avoid opening a new bin unless the existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Best-Fit logic: Penalize large post_residuals to favor tight packing
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead efficiency: If the next item can fit in the post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Bonus for "perfect" fit for the next item
        if (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }

    // 4. Avoid creating "sliver" waste (bins with small, unusable residuals)
    // If post_residual is small but > 0, it's often a bad spot unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Global state normalization:
    // If we have many open bins, prioritize closing the ones with the lowest residuals.
    if open_bins_count > 0 {
        let residual_diff = (post_residual as f64) - mean_residual;
        score += residual_diff * 0.2;
    }

    // 6. Last-chance penalty:
    // If fitting_bins_count is 1, we are forced into this bin if we don't open a new one.
    // Discourage new bin opening if this bin is a decent fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. Smaller is generally better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (small, unusable space).
    // We penalize residuals that are too small to fit the average remaining item size,
    // but large enough to waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if we know the next item, prioritize bins that can fit both
    // the current and the next item optimally.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize if the current placement forces a new bin for the next item.
            score += 10.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for opening new bins:
    // Only open a new bin if the current state is highly inefficient or if we are
    // near the end of the stream and need to clear space.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if there are existing bins that can fit the item.
            // Scale the penalty by the "tightness" of the current open bins.
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // If no other bin fits, this is mandatory.
            score -= 50.0;
        }
    } else {
        // Encourage packing into bins that are already "half-full" to keep the 
        // distribution of residuals uniform.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill_ratio;
    }

    // Final adjustment based on global state: 
    // As we near the end of the stream, prioritize aggressive packing.
    if progress > 0.9 {
        score -= (open_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We want to minimize post_residual to pack tightly
    let mut score = post;

    // Penalty for creating small, unusable gaps (1-9 range is often 'dead space')
    // We penalize the post_residual if it falls into the 1..9 range non-linearly
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 5.0;
    }

    // Lookahead coupling: If the next item is large, prioritize keeping space open.
    // If next_item_size > post_residual, we penalize this placement to save space.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if next_item > post && post > 0.0 {
            score += (next_item - post) * 2.0;
        }
    }

    // Stream progression adjustment:
    // Early in the stream, we are more conservative (penalize opening new bins).
    // Late in the stream, we prioritize clearing the remaining items.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We make it expensive early on, and cheaper as the stream progresses.
        score += (1.0 - progress) * 50.0;

        // If there are many open bins, we shouldn't open another one.
        score += open_bins_count as f64 * 2.0;
    }

    // Interaction with mean_residual:
    // If the current bin is "better" than the average open bin, favor it.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.5;
    }

    // Fitting bins count: If this is the only bin that fits the item, 
    // it's highly valuable, so we reduce the score to ensure it is chosen.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the least space (lower post_residual).
    // 2. Penalty for creating "stranded" space: if post_residual is small but > 0, 
    // it's often better to have a larger residual that can accommodate the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Penalize bins that become "dead" for the next item
            score += 40.0;
        } else if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item
            score -= 20.0;
        }
    }

    // 3. Harmonic class alignment:
    // Prefer post_residuals that are multiples of common item sizes (20, 25, 33) 
    // to keep bins aligned for future packing.
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 4. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (high fragmentation)
        // or if the current best fit is very poor (post_residual very high).
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Fragmentation control:
    // Penalize bins that drift too far from the mean residual of the set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Last-chance logic:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
