    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight (near-perfect).
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Only open a new bin if the item size is very large, reducing the efficiency of filling existing bins.
        if item_size < 50 {
            score += 40.0;
        }
    } else {
        // 4. Tightness Reward: Favor bins that leave very little space (Best Fit variant).
        // If the item fits well, reduce the score.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Scarcity Penalty: If this is the only bin that can fit the item, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize closing existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
