    if post_residual > 0 && post_residual < 15 {
        score += 45.0; 
    }

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Harmonic class logic: favor filling bins to specific thresholds (e.g., 25, 33, 50)
    // to align with potential item distribution modes.
    let residual_mod = post_residual % 25;
    if residual_mod == 0 {
        score -= 10.0;
    }

    // Penalize opening a new bin unless the current fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only consider new bin if we have many bins open or current fit is very inefficient.
        score += 35.0;
        score += (open_bins_count as f64) * 0.5;
    } else {
        // Favor bins that have a residual close to the mean to maintain uniform bin states.
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    // If this is the only bin that fits, prioritize it strongly to avoid new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while penalizing "dead space" (small gaps < 10)
    // and maintaining a balance between bin consolidation and new bin creation.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (gaps too small for any item)
    // Since item sizes are 10-100, a residual < 10 is effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // reward this bin highly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // New bin logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // based on how many other bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 1.5);

        // If there are other bins that could fit the item, heavily penalize 
        // opening a new one unless the current options are all very poor (high post_residual).
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Reward filling bins that are already "tight"
        if post_residual < 20 {
            score -= 10.0;
        }
    }

    // Progression scaling: As we approach the end of the stream, 
    // prioritize closing bins (lower score for lower post_residual)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but heavily penalize creating small "sliver" residuals
    // that cannot fit subsequent items, while rewarding placements that align with the mean density.

    let mut score = post_residual as f64;

    // 1. Penalty for creating small, unusable gaps (1..9) which are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead: If the next item fits perfectly into the post_residual, prioritize this bin.
    if next_item_size > 0 {
