                score -= 20.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
            }
        } else {
            // If the next item doesn't fit, penalize leaving a "wasted" space 
            // that is larger than the mean of current bins.
            score += 5.0 * (post_residual as f64 / (mean_residual + 1.0));
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if current fitting options are poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or the current fit is terrible.
        score += 35.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, reward it if it's the only one that fits the item.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // 4. Density Balancing:
    // Prefer bins that stay closer to the global mean residual to keep capacities uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
