        if open_bins_count > 0 {
            score += 40.0 * (1.0 + progress);
        }
    }

    // 5. Fitting Constraint: If this is the only bin that fits the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 6. Mean Residual Alignment: Avoid bins that deviate significantly from the average state to keep packing uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which we want to minimize (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (very small residuals) that are unlikely to be filled.
    // We penalize values between 1 and 9 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic threshold: As the stream progresses, become more conservative about opening new bins.
    // If it's a new bin, apply a non-linear penalty that scales with progress and open bins.
    if is_new_bin {
        // Penalty for opening a new bin increases as we have more bins open to reuse.
        // The term (1.0 - progress) encourages aggressive packing early and caution late.
        score += (open_bins_count as f64 * 2.5) * (1.0 + progress.powf(2.0));
    } else {
        // If it's an existing bin, reward it based on how close the post_residual 
        // is to the mean_residual of all bins (homogenization).
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // Interaction term: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize small residues that cannot accommodate common future items
    // If post_residual is small but > 0, it creates "dead space" (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Logic: If the next item is large, favor bins that accommodate it better.
    // If the next item is larger than the current post_residual, we penalize the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 3. Harmonic Packing: Favor bins that align with high-density integer fractions of capacity
    // (e.g., leaving a remainder that is a factor of 100 or 50)
    if post_residual > 0 {
        let remainder_mod = 100 % post_residual;
        score += remainder_mod as f64 * 0.5;
    }

    // 4. Global Density Control: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Fitting Constraint: If this is the last fitting bin, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, be more conservative with bin usage.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
