        // Specifically reward "tight" fits for the lookahead
        let gap = post_residual - next_item_size;
        score += gap as f64 * 0.8;
    }

    // 3. New Bin Management: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless we have no other good options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; 
        } else {
            score -= 10.0; // Bias towards opening a new bin if nothing else fits
        }
    }

    // 4. Global Consolidation:
    // If the post_residual is below the current mean, we are creating a "tight" bin.
    // Reward bins that pull the mean residual down to increase packing density.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Criticality: If this is the only bin that fits, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progression Bias: As we approach the end of the stream, 
    // prioritize tighter packing to reduce trailing empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual.
    // However, if post_residual is very small (e.g., < 5), it might be "too tight" 
    // for future items, so we apply a slight penalty for extreme tightness.
    if post_residual < 5 && post_residual > 0 {
        score += 2.5;
    }

    // 2. Lookahead Logic: If the next item exists, check if this bin can accommodate it.
    // If the current placement leaves a gap that perfectly fits the next item, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Penalty: If this is an empty bin, penalize it based on how many 
    // existing bins could have fit the current item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 15.0;
        // Also penalize new bins more heavily as we approach the end of the stream
        score += (step_index as f64 / total_items as f64) * 10.0;
    }

    // 4. Global State Awareness: If we are creating many bins, try to consolidate 
    // by penalizing bins that deviate significantly from the mean_residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Last Chance Heuristic: If this is the only bin that fits the item, 
    // heavily prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
