    // to encourage consolidation, but allow it if post_residual is near zero (perfect fit).
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = if is_new_bin {
        // Base cost for opening a new bin is high, modulated by progress and expected space waste
        (100.0 - item_size as f64) * (1.0 + progress) + 50.0
    } else {
        // Evaluate existing bin fit:
        // Favor post_residual close to 0 (Best Fit).
        // Penalty for leaving space that is smaller than the next item (lookahead).
        let mut s = post;

        if next_item_size > 0 {
            if post < next_item_size as f64 {
                // Heuristic penalty: creating a gap too small for the next item
                s += (next_item_size as f64 - post) * 1.5;
