        }

        // Interaction: Penalize bins that deviate significantly from the mean_residual
        // to keep usage density uniform across bins.
        s += (post - mean_residual).abs() * 0.5;

        s
    };

    // If this is the last fitting bin, prioritize it strongly to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (1-9)
    // as they create "dead" space that cannot accommodate common small items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 / (post_residual as f64).sqrt();
