    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            score += 35.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward filling bins to capacity to reduce open_bins_count
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 4. Scarcity Constraint: If this is the only bin that fits, prioritize it
