pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bins heavily early on, but allow them as the stream nears completion
    // to avoid forcing bad fits into limited space.
    let new_bin_penalty = if is_new_bin {
        25.0 + (30.0 * (1.0 - progress).powi(2))
    } else {
        0.0
    };

    // Calculate the "tightness" of the fit. 
    // We prefer post_residuals that are very small (Best Fit) OR 
    // post_residuals that perfectly match the lookahead item.
    let fit_score = post_residual as f64;

    // Lookahead logic: if the next item fits into the post_residual, 
    // we reward this placement significantly.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64)
    } else {
        0.0
    };

    // Penalize leaving "dead space" that is too small for any likely future item.
    // Small residuals (1-9) are usually useless, so penalize them non-linearly.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        10.0 / (post_residual as f64 + 0.1)
