    fit_score + new_bin_penalty + lookahead_penalty + scarcity_reward + deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic penalty: penalize residuals that are small but not zero (fragmentation)
    // If post_residual is small (e.g., < 10) but not 0, it is often "dead space".
    if post_residual > 0 && post_residual < 10 {
