    // 4. Threshold penalty for opening new bins
    // If this is a new bin (residual == capacity), add a high base cost
    if bin_residual == bin_capacity {
        score += 55.0;
        // Reduce the cost of a new bin if few bins are open or if we are late in the stream
        let progress = step_index as f64 / total_items as f64;
        score -= (progress * 20.0) + (open_bins_count as f64 * 2.0);
    }

    // 5. Harmonic coupling: avoid creating bins with residuals that are multiples of common item sizes
    // Modulo logic to discourage specific "unfit" gaps
    if post_residual % 20 == 0 && post_residual > 0 {
        score += 10.0;
    }

    // 6. Fitting count pressure: if this is the only bin that fits the current item, 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
