    // Stream progression coupling:
    // As we approach the end of the stream (progress -> 1.0), 
    // prioritize filling existing bins even if the fit is suboptimal
    // to avoid leaving items for new bins at the very end.
    let end_game_pressure = progress * 20.0;
    score -= end_game_pressure * (1.0 - (post / bin_capacity as f64));

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // The base cost of opening a new bin is high.
        score += 35.0;

        // If there are many open bins, we should avoid opening another one.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
