    // Small post_residual is good, but we penalize bins that create "dead zones" (e.g., 1-9 residual)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalty for unusable space
    }

    // 2. Lookahead optimization: If next_item_size fits in current post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Prevent opening a new bin if other options exist
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 50.0; // Heavy penalty for opening a new bin if existing ones can fit
        }
    } else {
        // 4. Balance the load: favor bins closer to the mean_residual to keep residuals uniform
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.1;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 6. Last-chance penalty: If this is the only bin that can fit, prioritize it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize values that 
    // are too small to fit common items (e.g., < 10), creating unusable "dust".
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin to keep the packing density high.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current 
    // configuration is extremely poor (high residual/low density).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the 
        // current mean residual is already quite high.
        score += 25.0 + (open_bins_count as f64 * 0.5) - (mean_residual * 0.1);
    }

    // 4. Scarcity Logic: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Temporal Smoothing: Adjust aggressiveness as the stream progresses.
    // In later stages, prioritize closing bins to reduce total count.
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
