    // more heavily as we progress through the stream, unless the current bin
    // is truly inefficient (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * (1.0 + 0.5 * (1.0 - progress));

    // If this is a new bin, apply a threshold penalty based on the mean residual of existing bins.
    // This forces the algorithm to prioritize filling existing bins if they are already tight.
    if is_new_bin {
