        // Penalize bins that are left with very small, unusable gaps (1-9)
        if post > 0.0 && post < 10.0 {
            score += 25.0 * (1.0 - (post / 10.0));
        }
    }

    // Encourage packing into bins that are the "last chance" for the current item
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
