    // 3. Mean Residual Balancing: Avoid bins that deviate significantly from the average
    // This helps in keeping bin fullness uniform across the set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Scarcity Handling:
    // If this is the only bin that can fit the item, prioritize it to avoid new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
