    let post_res = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening new bins heavily, but decrease penalty as we approach the end of the stream
    // to allow for better packing density in the final stages.
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + 10.0
    } else {
        0.0
    };

    // Best-fit base: prioritize bins where post_residual is small.
    // We add a non-linear penalty for "wasted" space (post_residual squared).
    let fit_score = post_res.powi(2) / 10.0;

    // Lookahead interaction: if next_item_size exists, penalize bins that cannot fit it
    // after placing the current item.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
