    // Penalize the new bin candidate (where bin_residual == bin_capacity)
    // as the stream progresses, but keep it as a fallback.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = if is_new_bin {
        (1.0 - progress) * 150.0 + 20.0
    } else {
        post
    };

    // Non-linear coupling: Favor smaller post_residuals (Best Fit),
    // but penalize creating "dead space" that is too small for common future items.
    // If next_item_size is large, prioritize bins that can accommodate it.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 40.0 * (1.0 - progress);
    }

    // Encourage packing into bins that are already "tight" to keep open_bins_count low.
    // We utilize mean_residual to identify bins that are better candidates for packing.
    if !is_new_bin {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= 0.5 * deviation;
    }

    // If this is the last chance to fit the item in an existing bin,
    // apply a significant discount to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Quadratic penalty on post_residual to avoid leaving "slivers" of space
    // that are unlikely to fit future items.
    score += (post * post) / (bin_capacity as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
