    // We heavily penalize post_residual values that create "sliver" gaps (1..9) as they are rarely useful.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open bin pressure: If we have many bins open, penalize opening a new one or using an empty bin
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // Discourage opening a new bin if we have plenty of space in existing bins
        if mean_residual > 20.0 {
            score += 40.0;
        }
    }

    // 3. Lookahead utility: If the next item is large, favor bins that keep more space
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot accommodate the next item if possible
            score += 25.0;
        }
    }

    // 4. Fitting constraints: If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with bin openings
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

