            score += 60.0 + (item_size as f64 * 0.2);
        } else {
            // Reward opening a new bin if it's the only option
            score -= 10.0;
        }
    }

    // 5. Mean residual balancing:
    // Try to keep bin residuals close to the mean to avoid extreme fragmentation.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    // 6. Progression Scaling:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

