    // 2. Harmonic Class Logic: penalize bins that leave space too small for common item fragments.
    // If post_residual is < 20, it's often wasted space; penalize it heavily.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 / (post_residual as f64 + 1.0);
