    // 5. Progression adjustment: as we near the end of the stream, prioritize closing existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * progress;
    }

    // 6. Mean Residual Balancing: avoid creating outliers in bin fullness.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

