    // Mean residual alignment:
    // Penalize bins that deviate significantly from the mean residual to keep bin levels uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last chance logic:
    // If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
