        }
    }

    // 3. Lookahead Logic: If the next item is large (e.g., > 50), favor leaving larger residuals
    // This helps prevent fragmentation for future large items
    if next_item_size > 50 {
        // If placing this item creates a post_residual too small for the next big item, penalize
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // 4. Tight Fit Reward: If the item fits perfectly, prioritize it heavily
    if post_residual == 0 {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the bin is nearly full but not empty, reward it
    // to consolidate items in the same bin
    if post_residual < 15 && post_residual > 0 {
