    // 4. Thresholding/Filling:
    // If a bin is the only one that can fit the current item, prioritize it heavily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. New Bin Logic:
    // Only open a new bin if the current fit is extremely poor (post_residual is very large).
    // The new bin call has bin_residual == bin_capacity (100).
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin
