        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: As we approach the end of the stream, 
    // prioritize closing bins (lower post_residual) more aggressively.
    score += (1.0 - progress) * (mean_residual - post_res).abs();

    // Interaction with open_bins_count: discourage opening too many bins early on.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on
    // how many bins are already open to force consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) * (1.0 + progress);
    }

    // Reward bins that are nearing exhaustion (lower post_residual) 
    // when we have many open bins.
    if open_bins_count > 5 {
        score -= (1.0 - (post_res / bin_capacity as f64)) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo penalty: favor bin configurations that leave room for common item sizes
    // We penalize residuals that are small but unusable (1..9 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: If next_item_size is large, favor larger post_residuals
    // If next_item_size is small, favor tightest fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin cannot fit the next item, penalize if it's the only fitting bin
            score += 20.0 / (fitting_bins_count as f64 + 1.0);
        } else {
            // This bin can fit the next item, reward this
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 4. Modulo/Harmonic bias: Favor residuals that align with common fractions of C
    // 100/2=50, 100/3=33, 100/4=25. If post_residual is near these, it's a "good" state.
    let harmonic_bias = ((post_residual % 25) as f64).abs();
    score += harmonic_bias * 0.2;

    // 5. Global state normalization:
    // If we are late in the stream, be more aggressive about filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 2.0;

    // 6. New Bin Threshold:
    // If bin_residual == bin_capacity, this is a new bin.
    // Penalty is high to force Best-Fit behavior, but decreases as open_bins_count grows.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64 * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual ranges that are too small to fit typical future items (10-30).
    // If post_residual is in (0, 10), it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If the next item is large, avoid leaving small residuals now.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, favor keeping it tight.
    // If we are considering a new bin (bin_residual == bin_capacity), add a penalty to discourage 
    // fragmenting space unless the existing bins are already very full.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already quite small
        // or if we have very few bins open.
        score += 15.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
    } else {
        // For existing bins, reward bins that are already closer to the mean residual to consolidate space.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 4. Scarcity adjustment: If this is the last bin that can fit the item, give it a slight preference
    // to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 5. Progression scaling: As the stream nears the end, become more aggressive about 
    // filling existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
