    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // The base score already favors smaller post_residual.

    // 2. Lookahead Integration: If we have a next item, avoid creating "dead zones".
    // If post_residual is too small for the next item, penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // 3. Dynamic Thresholding for New Bins
    if is_new_bin {
        // If only one bin fits the item, opening a new one is usually bad (unless the fit is terrible)
        if fitting_bins_count > 0 {
            score += 40.0 + (20.0 * progress);
        } else {
            // If no existing bin fits, we must open a new one. 
            // Return a low score to ensure this is selected.
            score = -100.0;
        }
    } else {
        // 4. Global State Balancing: Use mean_residual to prevent fragmentation.
        // If this bin's post_residual is much lower than the mean, we are "tightening" the bin.
        if (post_residual as f64) < mean_residual {
            score -= 5.0 * (1.0 - progress);
        }

        // 5. Critical Constraint: If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "fragmented" space (too small for future items)
    // The penalty is higher when the residual is small but non-zero, 
    // especially as we approach the end of the stream.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 10.0 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Reward utilizing bins that are already "tight" to keep open_bins_count low.
    // Use the difference from mean_residual to encourage bin consolidation.
    let consolidation_reward = (bin_residual as f64 - mean_residual).abs() * 0.5;

    // Lookahead interaction: If the next item fits into the post_residual, 
    // strongly incentivize this bin to minimize future bin openings.
    let lookahead_bonus = if next_item_size > 0 && post_res >= next_item_size as f64 {
        -40.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // heavily incentivize using it to avoid opening a new bin unnecessarily.
    let preservation_incentive = if fitting_bins_count == 1 {
        -50.0
    } else {
        0.0
    };

    // New bin bias: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the score is lower than existing options.
    // We penalize opening new bins early in the stream, but allow it if no good fits exist.
    let new_bin_penalty = if bin_residual == bin_capacity {
        30.0 + (progress * 20.0)
    } else {
        0.0
    };

    let score = post_res + fragmentation_penalty + consolidation_reward + lookahead_bonus + preservation_incentive + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
