    // We add a penalty for "unusable" small residuals that cannot accommodate common items
    let waste_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: If the next item fits into the current bin's post_residual, 
    // reward this bin heavily to encourage packing pairs.
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        - (next_item_size as f64 * 2.0)
    } else {
        0.0
    };

    // Dynamic thresholding: As we approach the end of the stream, 
    // tighten the requirements for opening new bins (penalize new bins more).
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * (1.0 + progress)) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Coupling: Use mean_residual to avoid creating bins that are significantly 
    // below the average efficiency, which preserves capacity for future items.
    let deviation_penalty = if bin_residual != bin_capacity && post < mean_residual {
        (mean_residual - post) * 2.0
    } else {
        0.0
    };

    // Final score: Lower is better. 
    // We favor post_residual, apply penalties for fragmentation, 
    // and reward packing lookahead items.
