    }

    // 4. Scarcity Constraint: If this is the last chance for the current item to fit, 
    // prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Progression Bias: As we near the end of the stream, prioritize closing bins (minimizing residuals)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for opening a new bin if other bins are available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 85.0;
    }

    // Best-Fit strategy: prioritize filling bins tightly
    // We want post_residual to be small, but not so small that it becomes unusable (the "fragmentation" trap)
    // A post_residual between 1 and 9 is often a "dead zone" for 10-80 sized items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if we have a next item, try to leave exactly enough space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect matches for the next item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (50.0 / (1.0 + fit_diff));
        } else {
            // If the next item cannot fit, penalize leaving a small useless gap
            score += 15.0;
        }
    }

    // Global balance: if the mean residual is high, we are being too loose; 
    // favor bins that are already closer to the mean to consolidate space
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // Progression: As we near the end of the stream, be more aggressive about filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // If this is the only bin that fits, heavily prioritize it to avoid unnecessary new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. Smaller is generally better (Best Fit),
    // but we want to avoid creating "slivers" (very small, unusable residuals).
    let mut score = post_residual as f64;

    // 1. Penalty for creating slivers: residuals between 1 and 9 are often "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead logic: If the next item fits into this post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
