    // 3. Global state balance: If we have many open bins, penalize opening a new one heavily.
    if is_new_bin {
        score += 40.0 + (open_bins_count as f64 * 2.0);
        // Late game: be more aggressive about opening new bins to pack remaining items efficiently
        score -= (progress * 30.0);
    } else {
        // If this is the last chance for this item (only 1 bin fits), prioritize it.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Prefer bins that are already "fuller" (lower residual) to consolidate space
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // 4. Dynamic scaling for small items:
    // If the item is small, we want to pack it into existing bins rather than opening new ones.
    if item_size < 20 && is_new_bin {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead zones": if post_residual is small but > 0, 
    // it is often worse than 0 (perfect fit). Penalize small remainders non-linearly.
    if post_residual > 0 && post_residual < 15 {
        score += 15.0 - post_res;
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, penalize bins that leave a post_residual 
    // smaller than the next item's size, as this forces a new bin later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
