    // Global Efficiency Pressure:
    // As the stream progresses, we become increasingly strict about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are early in the stream or if open_bins_count is low,
        // otherwise, heavily penalize opening new bins to force consolidation.
        score += (open_bins_count as f64 * 2.0) + (progress * 50.0);
    } else {
        // If the bin is already open, favor placements that keep the bin's 
        // residual close to the mean_residual of other bins to maintain uniformity.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Final scaling: favor bins that are nearly full if they can accommodate the current item
    // to keep the number of active bins (open_bins_count) low.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

