    // We aim for post_residual == 0 (perfect fit).
    score += (post_residual as f64).powf(1.2);

    // 2. Harmonic Class Coupling: 
    // If post_residual is small but not zero, it creates "dead space" that is hard to fill.
    // If the next item can fit into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

