        // If it's the only option, reduce penalty
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    // 4. Thresholding based on mean_residual:
    // If the current post_residual is significantly worse than the average, penalize it.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // 5. Lookahead efficiency:
    // If fitting_bins_count is 1, this bin is the last chance for this item.
    // We must prioritize filling it unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0;
    }

    // 6. Modulo-based "harmonic" alignment:
    // Encourage configurations that leave remaining space as multiples of common item sizes (e.g., 20, 25).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
