    }

    // 3. Fragmentation Control: Avoid creating too many bins by penalizing new bin creation 
    // unless the fit in existing bins is extremely poor (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // If we have many open bins, opening another one is expensive.
        score += (open_bins_count as f64) * 5.0;
