    }

    // 4. Harmonic Alignment: Favor bins that align with "clean" divisions of capacity.
    // Bins that result in a post_residual of 0 (perfect fit) are highly prioritized.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 25 == 0 {
        // Reward residuals that are multiples of 25 (e.g., 25, 50, 75)
        score -= 15.0;
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
