        score += deviation * 0.5;
    } else {
        // If this is the only bin that fits, we are forced to use it.
        // If it's a new bin (residual == capacity), penalize based on progress.
        if bin_residual == bin_capacity {
            score += 150.0 * (1.0 - progress);
        }
    }

    // Non-linear coupling: penalize opening new bins significantly more as 
    // the stream progresses, effectively forcing tight packing later on.
    if bin_residual == bin_capacity {
        score += 100.0 * progress.powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
