    };

    // Reward bins that keep the mean residual balanced relative to incoming item sizes
    // This helps pack items of similar sizes together
    let balance_factor = (post - mean_residual).abs() * 0.5;

    // Lookahead: if the next item is large, penalize small residuals in current bin
    // This preserves space for future large items
