    // Favor bins that are more "tightly packed" generally, 
    // but normalize by the number of bins to prevent fragmentation
    let fragmentation_penalty = (open_bins_count as f64) * 2.0;

    // Combine factors
    // Lower score is better
    let score = post 
        + dead_space_penalty 
        + balance_factor 
        + lookahead_penalty 
        + completion_penalty 
        + fragmentation_penalty;

