    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Global Efficiency: Penalize opening new bins when existing ones have capacity.
    // If this is a new bin, increase its score to make it less attractive.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Tight Fit Reward: Strongly favor bins that result in a perfect fit (post_residual == 0).
    if post_residual == 0 {
        score -= 30.0;
    }

    // 5. Pressure scaling: As the stream progresses, favor packing tighter to 
    // avoid stranding large items in the final stages.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the average
    // to keep the bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

