    // We penalize post_residual values that are smaller than the smallest likely items (e.g., < 10)
    // but only if we are not near the end of the stream.
    if post < 10.0 && post > 0.0 {
        score += (10.0 - post) * 5.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, we penalize this bin for being unable to take the next item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 2.5;
    }

    // Dynamic thresholding for opening new bins:
    // If residual == cap, we are evaluating a brand new bin.
    // We only open a new bin if the current 'best' fit is very poor (high post_residual).
    if residual == cap {
        // If there are no other bins that can fit the item, we must open a new one.
        if fitting_bins_count == 0 {
            score = -100.0; // Force selection
        } else {
            // Otherwise, opening a new bin is expensive.
            // We scale the cost of a new bin by the progress; as we reach the end,
            // we become more conservative about opening new bins.
            score = 15.0 + (progress * 50.0);
        }
    } else {
        // Reward bins that bring the mean residual closer to the ideal (which is 0).
        // This encourages filling bins tightly.
        score += (post - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic: 
    // If the remaining space is small, it's likely "dead space". 
    // We penalize residuals that are smaller than the smallest possible item size (10) 
    // but greater than 0, as they are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 3. Lookahead Integration:
    // If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for accommodating the next item
        } else {
            score += 5.0; // Penalty if this bin cannot fit the next item
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // all existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score += 45.0;

        // If we have many open bins, we should favor using them over a new one
        score += (open_bins_count as f64) * 0.5;
    } else {
        // Reward bins that have residuals close to the mean to maintain balance
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    // 5. Urgency:
    // If this is the only bin that can fit the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Strict Dead Space Avoidance & Adaptive Bin Pressure
    // Objective: Minimize post_residual unless it creates an unusable gap (1..9),
    // while penalizing the opening of new bins unless necessary.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the resulting gap is too small to fit any expected item (1-9),
    // it is highly undesirable as it creates "orphaned" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // reward this bin heavily to create a "perfect" packing pair.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: Penalize opening a new bin if other bins can accommodate the item.
    // If this is a new bin (residual == capacity), add a penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If there are other bins that could fit this, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean Residual Balancing: If this bin's post_residual is much worse than the current average,
    // penalize it to encourage balancing the fullness of bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more aggressive
    // about closing bins (reducing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
