    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item cannot fit in this post_residual, 
    // penalize the choice unless it's the only bin available.
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when current bins are underutilized.
    // We heavily penalize the "New Bin" candidate (bin_residual == bin_capacity)
    // if we have existing bins that could accommodate the item.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Add a cost proportional to existing bin count to discourage fragmentation.
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Best-Fit Logic: Reward bins that become "tight" (low post_residual).
        // This naturally favors filling bins as much as possible.
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // 5. Progression adjustment: As we approach the end of the stream, 
    // become more aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
