    // 2. Avoid opening new bins unless necessary
    // If the bin is brand new (residual == capacity), add a penalty based on open_bins_count
    // to discourage fragmentation early in the stream.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead integration:
    // If next_item_size fits in the post-placement space, reward this bin choice.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.2;
    }

    // 4. Global state pressure:
    // If fitting_bins_count is low, we are running out of options for this item.
    // Discourage opening a new bin if we have other viable existing bins.
    if fitting_bins_count > 0 && bin_residual == bin_capacity {
        score += 30.0;
    }

    // 5. Dynamic time horizon:
    // As the stream progresses, become more conservative (stricter fitting requirements)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.8;
    }

    // 6. Balance residual space:
    // If this bin is significantly less efficient than the current average, penalize it.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Base score is the residual space: we prefer smaller residuals (Best Fit)
    // We use a quadratic penalty for post_residual to discourage leaving large gaps
    let mut score = post * post;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on 
    // the current progress to discourage early new-bin creation.
    if bin_residual == bin_capacity {
        // As the stream progresses, the penalty for opening a new bin decreases 
        // because the probability of finding a perfect match later diminishes.
        score += (bin_capacity as f64 * 2.0) * (1.0 - progress).powf(0.5);
    }

    // Lookahead logic:
    // If the next item exists, penalize bins that leave a residual smaller than next_item_size.
    // This effectively implements a variation of "Next Fit Decreasing" logic.
    if next_item_size > 0 {
        if post < next_item_size as f64 && post > 0.0 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Density normalization:
    // Favor bins that align with the current mean_residual to maintain uniformity
    // across open bins, preventing 'fragmentation' of available space.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.5;

    // Constraint: If this is the only bin that can fit the item, heavily prioritize it
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot accommodate typical items).
    // If post_residual is in the range (0, 10), it is very likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
