    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream.
        score += 25.0 + (progress * 20.0);
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item,
    // we should favor it unless it's a very poor fit (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Residual Alignment: Favor bins where the post_residual is a multiple
    // of common item sizes (harmonic logic).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    // 6. Global Balance: Penalize opening bins if we already have many open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
