    }

    // 4. Mean Residual Balancing:
    // Discourage bins that deviate significantly from the current mean residual to keep bin levels uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the
    // current fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have no other choice or current options are bad.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If it's the last chance bin (fitting_bins_count == 1), reward it to avoid opening a new bin.
        if fitting_bins_count == 1 {
