    // we heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = post_residual - next_item_size;
        // Reward small leftovers after the next item (synergy)
        score -= (100.0 - leftover as f64) * 1.5;
    }

    // 3. Mean Residual Balancing: Prevent fragmentation.
    // If post_residual is significantly lower than the mean of other bins, 
    // it's a good candidate for "closing" that bin to a tight state.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. New Bin Threshold: Discourage opening new bins unless the fit is very poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If it's the only bin that fits (fitting_bins_count == 0), reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // 5. Progression Scaling: As we near the end of the stream, prioritize closing bins
    // by penalizing large post_residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best Fit Decreasing dynamic variant)
    // We prioritize keeping the post_residual as small as possible (Best Fit),
    // but penalize creating "dead zones" that cannot fit future items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit objective)
    let mut score = post_residual as f64;

    // Penalize opening a new bin if we have fitting space elsewhere
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 - progress); // Heavy penalty for opening new bin early
        } else {
            score -= 50.0; // Reward opening new bin if necessary
        }
    }

    // Lookahead: If next_item_size is large, penalize small post_residual that might strand it
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // This is a "fragmentation" penalty: we created space that can't fit the next item
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        } else if post_residual >= next_item_size {
            // Reward placements that keep the next item viable
            score -= 10.0;
        }
    }

    // Global state: penalize creating bins that deviate significantly from the mean residual
    // This promotes uniform filling across all open bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // Edge case: if we are near the end of the stream, prioritize space density
    if progress > 0.9 {
        score *= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Penalize creating tiny, unusable gaps that are too small for common items (Best-Fit principle).
    // If post_residual is < 10, it's likely "dead space".
    let gap_penalty = if post_residual < 10 && post_residual > 0 { 
        (10.0 - post) * 5.0 
    } else { 
        0.0 
    };

    // Use lookahead to check if the next item fits into the current potential post_residual.
    // If it fits, we reward this placement to keep bins packed tightly.
    let lookahead_reward = if next_item_size > 0 && (post_residual >= next_item_size) {
        -20.0 * (1.0 - (post / capacity))
    } else {
        0.0
    };

    // Dynamic preference: early in the stream, prefer keeping bins open (low open_bins_count).
    // Later in the stream, prioritize closing bins to reduce the final count.
    let stream_pressure = progress * (open_bins_count as f64);

    // If bin is empty (new bin candidate), penalize it more heavily early on,
    // but allow it if the fitting options are poor (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 40.0 + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Combine factors:
    // 1. post: smaller is generally better (Best Fit).
    // 2. gap_penalty: avoid tiny fragments.
    // 3. lookahead_reward: favor bins that can take the next item.
    // 4. new_bin_penalty: discourage opening bins unless necessary.
    let mut score = post + gap_penalty + lookahead_reward + (stream_pressure * 0.1) + new_bin_penalty;

    // Final tie-breaker: prefer bins that are already closer to capacity to consolidate space.
    score += (capacity - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize keeping the residual small to maximize density.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Alignment: Reward states where post_residual is a multiple 
