    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high.
        score += 45.0;
        // If we have many open bins that could fit the item, discourage new bin creation.
        score += (fitting_bins_count as f64) * 20.0;
    }

    // 5. Global Density Balancing: If the current bin's residual is much 
    // larger than the global mean_residual, penalize it to force consolidation.
    if (bin_residual as f64) > (mean_residual * 1.2) {
        score += 10.0;
    }

    // 6. Last Chance Logic: If this is the only bin that fits the current item, 
    // take it regardless of fit quality to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
