}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (tiny residuals that are hard to fill)
    // Residuals < 10 are generally difficult for the specified item distribution
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead matching
    // If next_item_size is known, favor bins where the remaining space matches it exactly
    if next_item_size > 0 {
