        // If the post_residual is exactly the next item size, prioritize this bin heavily
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 3. Balance against mean_residual to prevent uneven load distribution
    // Penalize bins that deviate significantly from the average fullness
    let deviation = (post_residual as f64 - (mean_residual - item_size as f64)).abs();
    score += deviation * 0.2;

    // 4. Strategic New Bin Control
    // If bin_residual == bin_capacity (New Bin Candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit quality is poor across all open bins
        // or if we are nearing the end of the stream and need to clear space.
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins can fit the item
            score += 65.0;
        }

        // Progress-based scaling: Be more conservative with new bins as the stream nears completion
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Prefer filling bins that have less space to reduce the count of active bins
    // This effectively implements a Best-Fit behavior
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
