    // If we are near the end of the stream, prioritize closing bins.
    score -= (open_bins_count as f64 * 0.2);
    score += (progress * 10.0);

    // 5. New Bin Thresholding:
    // If this is a new bin (residual == capacity), add a significant penalty to force
