pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Harmonic/Residual-Efficiency with lookahead awareness.

    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize small post-residuals (tight fits).
    // Penalize large post-residuals as they create "dead space".
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Synergy: If the next item fits into the current post-residual, 
    // heavily reward this bin to create a "perfect pair" or "perfect triplet".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;

        // Bonus for leaving a very small gap after the next item (tight packing).
        let second_post_residual = post_residual - next_item_size;
        if second_post_residual < 10 {
            score -= 20.0;
        }
    }

    // 3. Harmonic Penalty: If post_residual is small but not zero, it's often 
    // worse than a larger residual that might fit a future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global Density Control: Favor utilizing existing bins when the stream is 
    // near completion to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to progress and open bins.
        // Opening a new bin is expensive.
        score += 40.0 * (1.0 - progress) + (open_bins_count as f64 * 2.0);
    }

    // 5. Fitting Constraint: If this is the only bin that fits, prioritize it 
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the 
    // average efficiency to keep the packing uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are small but not zero.
    // Gaps between 1 and 9 are often "dead" because the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, apply a heavy penalty based on existing open bin density.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead Sensitivity: If the next item is large, prioritize tighter fits now
    // to preserve capacity for the upcoming item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placements that block the next item from fitting in this bin.
            score += 15.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Residual Balancing: Favor bins that stay closer to the global mean residual
    // to prevent fragmented bin usage.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progression Factor: As we reach the end of the stream, be more aggressive
    // about packing tightly to close out bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any likely future item.
    // If post_residual is small but > 0, it's often a bad spot unless it fits the next item.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // 2. Lookahead matching: Reward bins that fit the next item perfectly (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= (100.0 - waste) * 0.8;
    }

    // 3. Prefer bins that keep the mean_residual high (maintaining flexibility for larger items).
    // If placing the item makes the bin's residual significantly lower than the global mean, penalize it.
    if (post_residual as f64) < (mean_residual * 0.7) {
        score += 20.0;
    }

    // 4. Strategic decision for New Bin:
    // Only open a new bin (bin_residual == bin_capacity) if existing fits are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have existing capacity.
            score += 65.0;
        }
    } else {
        // 5. Prefer Best-Fit: Lower post_residual is generally better to pack bins tightly.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 6. Progressive tightening: As the stream nears the end, be more aggressive with space.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: The remaining space after placement. Lower is generally better (Best-Fit).

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize empty bin opening: Only open a new bin if the fit is extremely poor
    // or if we have no other choice.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, scaled by how much capacity we have left elsewhere.
        // If we have many open bins, opening a new one is very expensive.
        score += 45.0 + (open_bins_count as f64 * 2.0);
    } else {
        // 2. Lookahead optimization (k=2): 
        // If next_item_size exists, favor bins that can accommodate it.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // Penalize placements that block the next item from fitting in this bin.
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else {
                // Reward placements that keep the bin "friendly" for the next item.
                score -= 10.0;
            }
        }

        // 3. Global state adaptation:
        // If mean_residual is high, we are wasting space globally. 
        // Be more aggressive in filling existing bins (Best-Fit bias).
        if mean_residual > 30.0 {
            score -= (30.0 - (post_residual as f64).min(30.0)) * 0.5;
        }

        // 4. Dynamic time horizon:
        // As we reach the end of the stream, prioritize closing bins over opening new ones.
        if progress > 0.8 {
            score -= (post_residual as f64) * 0.2;
        }
    }

    // 5. Critical constraint: If this is the last fitting bin, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish high post_residual (Best Fit)
    // We want to minimize post_residual, but we also want to avoid creating "dead space" 
    // that is too small for any future items (especially if next_item_size is large).
    let mut score = post_residual as f64;

    // Penalty for creating a bin with a small residual that is unlikely to fit common items
    // If post_residual is in (0, 10), it is very likely to be wasted.
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if we have a next_item, penalize bins that can't fit it
    if next_item_size > 0 && !is_new_bin {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // New bin dynamic thresholding:
    // As we progress through the stream, become more conservative about opening new bins.
    if is_new_bin {
        // Base cost of opening a new bin is high, but decreases slightly as we reach the end
        // to ensure we don't end up with many half-empty bins at the very end of the stream.
        let new_bin_cost = 45.0 + (10.0 * progress);

        // If there are many fitting bins, opening a new one is almost always bad.
        let availability_bonus = (fitting_bins_count as f64).min(3.0) * 15.0;
        score = new_bin_cost + availability_bonus;
    } else {
        // Favor bins that are already "tight" to keep the mean_residual low
        score += (post_residual as f64 - mean_residual).abs() * 0.5;

        // If this is the last fitting bin, prioritize it to avoid opening a new one
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1101: Harmonic Partitioning with Lookahead-Aware Residual Targeting
    // We aim to minimize post_residual, but heavily penalize "sliver" creation (residuals < 10)
    // and prioritize bins that can accommodate the next_item_size via harmonic thresholds.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones" (residuals too small for common items)
    // If post_residual is in the range [1, 9], it's often a waste.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 2. Lookahead Coupling: If next_item_size is known, favor bins that accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for keeping the bin viable for the next item
            score -= 25.0;
        } else {
            // Penalty if this choice forces a new bin for the next item
            score += 15.0;
        }
    }

    // 3. Harmonic balancing: Prefer bins that are closer to the mean residual to keep distribution uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.5;

    // 4. Strategic new-bin avoidance: 
    // If fitting_bins_count is low (e.g., 1), we are at a bottleneck.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing capacity
            score += 60.0;
        } else {
            // Must open a new bin, neutralize the score
            score = 30.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize tightest fit.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
