    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Harmonic Class Logic: Modulo-based reward for "round" numbers that maximize bin utilization.
    // Completing a bin (post_residual == 0) is the highest priority.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 25 == 0 {
        score -= 10.0; // Favor leaving exactly 25, 50, or 75 space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
