    // Penalize leaving a residual that is too small to fit common items (below 10),
    // unless it is exactly 0 (which is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global balance:
    // If we have many open bins, penalize creating more by increasing the cost of new bins.
    if bin_residual == bin_capacity {
