    }

    // 5. Mean residual alignment:
    // If this bin's post_residual is closer to the mean_residual of other bins, 
    // it keeps the bin distribution uniform (good for future packing).
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    // 6. Urgency:
    // If this is the only fitting bin, prioritize it to avoid creating a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
