pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We add a penalty for leaving "unusable" small gaps (e.g., < 10) 
    // unless the item fits perfectly (post == 0).
    let gap_penalty = if post > 0.0 && post < 10.0 { 25.0 } else { 0.0 };

    // Lookahead interaction: If the next item is large, prioritize keeping 
    // larger residuals open. If next item is small, prioritize tighter fits.
    let lookahead_factor = if next_item_size > 0 {
        (next_item_size as f64 - post) * 0.5
    } else {
        0.0
    };

    // Progression scaling: As we reach the end of the stream, prioritize 
    // filling existing bins more aggressively to avoid opening new ones.
    let density_pressure = (open_bins_count as f64 / (step_index as f64 + 1.0)) * 50.0 * progress;

    // If this is a new bin (residual == capacity), we penalize it based on 
    // how many other bins could have taken the item. If fitting_bins_count is high,
    // we heavily discourage opening a new bin.
    let new_bin_penalty = if residual == bin_capacity as f64 {
        (fitting_bins_count as f64 * 40.0) + (1.0 - progress) * 20.0
    } else {
        0.0
    };

    // Combine into a non-linear objective function
    let score = post 
        + gap_penalty 
        + lookahead_factor 
        + new_bin_penalty 
        - density_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
