        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin significantly to prioritize "two-item" packing.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 40.0 * (1.0 - (next_item_size as f64 / post));
    }

    // Dynamic constraint: As the stream progresses, favor packing tighter to 
    // avoid stranding empty bins at the end.
    let tightness_penalty = (open_bins_count as f64) * progress * 5.0;
    score += tightness_penalty;

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // Only open if the current fit is extremely poor (post_residual is very high)
    if bin_residual == bin_capacity {
        // If we have fitting bins, opening a new one is usually bad.
        // We set the base score of a new bin high, then subtract based on 
        // the average quality of existing bins to see if we can do better.
        score = 60.0 + (mean_residual * 0.5);
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Non-linear coupling: Reward bins that stay near the mean residual to keep
    // distribution uniform across open bins.
    let deviation = (residual - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
