    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global state: If we have many bins open, penalize opening a new one.
    // If this is a new bin (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Strong penalty for opening a new bin if others exist
            score += 50.0 + (open_bins_count as f64 * 2.0);
        }
        // As we approach the end of the stream, be more conservative about opening bins.
        score += progress * 30.0;
    } else {
        // If this bin is tight, reward it to keep it as the primary target.
        // Balancing the mean residual: if this bin is below the mean, it's a good candidate.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Scarcity: If this is the only bin that can fit the item, prioritize it highly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Dynamic thresholding: discourage creating bins that are nearly empty (high residual)
    // unless necessary.
    if post_residual > 70 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
