pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (small residuals that likely won't fit future items)
    // If post_residual is small (e.g., < 10), it is a high-quality packing unless it's 0.
    // We penalize values that are "just slightly too large" for common items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: Prioritize bins where the post_residual can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent fit for the next item, heavily reward this bin
            score -= 60.0;
        } else {
            // Potential penalty if we leave a gap that cannot fit the next item
            score += 15.0;
        }
    }

    // 3. Pressure to consolidate: If this is the last fitting bin, prioritize it to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Mean Residual coupling: Penalize bins that deviate too far from the average,
    // as we want to keep residual distribution uniform to increase packing density.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. New Bin Logic: If bin_residual == bin_capacity, this is a fresh bin.
    // We only want to open a new bin if the score of current bins is very poor.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high; only choose if current open bins are very bad
        score = 80.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Progression scaling: As we reach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are statistically the hardest to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Best-Fit strategy: reward bins that end up closer to full (lower post_residual)
    // The base score is already post_residual, so we refine it.

    // Lookahead logic: If a future item exists, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next item
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize bins that block the next item from fitting
            score += 20.0;
        }
    }

    // Global state awareness: 
    // If we are nearing the end of the stream, prioritize packing tightly (Best-Fit).
    // If we are early, prioritize keeping bins open to maintain flexibility.
    if progress < 0.3 {
        // Early stage: penalize closing bins too fast, favor high-residual bins
        score += (bin_residual as f64) * 0.1;
    } else {
        // Late stage: favor tight packing (smaller post_residual)
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // Dynamic threshold: discourage opening a new bin unless the fit is extremely poor
    if bin_residual == bin_capacity {
        // If this is a new bin candidate, add a cost based on the number of open bins
        // This effectively implements a dynamic "Next Fit" vs "Best Fit" transition
        score += 30.0 + (open_bins_count as f64 * 2.0);

        // If we have fitting bins, only open a new one if all current fits are terrible
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Penalize creating bins that deviate significantly from the mean residual
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residuals (Best Fit)
    // We want to minimize post_residual, but prioritize bins that leave very little space
    // for future items, while accounting for the lookahead.
    let mut score = post_res;

    // Penalty for creating "dead zones": if the post_residual is too small to fit any 
    // likely future item, it is effectively wasted space.
    // We use a non-linear sigmoid-like curve on the post_residual.
    let waste_penalty = (100.0 - post_res).powf(1.5) * 0.1;
    score += waste_penalty;

    // Lookahead coupling: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Progression coupling: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize the total count (prevent new bin openings).
    let completion_urgency = progress * 50.0;
    if fitting_bins_count > 0 {
        score -= completion_urgency / (fitting_bins_count as f64 + 1.0);
    }

    // Dynamic thresholding: If this is an empty bin (new bin candidate),
    // add a cost based on the number of open bins and current mean_residual.
    // This discourages opening new bins unless the existing ones are truly poor fits.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0) - (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Harmonic/Residual-Efficiency.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (tiny residuals that likely cannot fit future items).
    // If post_residual is in range [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that accommodate it.
    // If next_item_size fits in the post_residual, reward the bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Pressure management: If this is the last chance for this item, reduce penalty for opening new bins.
    // However, if we have many fitting bins, penalize opening a new one heavily.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0; // Strong penalty for opening a new bin if an existing one fits
        } else {
            score -= 20.0; // Slight incentive to open a new bin if nothing else fits
        }
    }

    // 4. Global state coupling: Normalize based on the density of open bins.
    // If mean_residual is low, we are running out of space; prioritize tight packing.
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += density_factor * 5.0;

    // 5. Progression weighting: As we approach the end of the stream, prioritize 
    // closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

