    }

    // Dynamic thresholding: As the stream progresses, become more aggressive in packing tightly.
    // We penalize opening a new bin (where bin_residual == bin_capacity) more as we near the end.
    if bin_residual == bin_capacity {
        score += 20.0 + (progress * 50.0);
    }

    // Favor bins that are already "half-full" to keep the number of open bins low,
    // but balance this with the mean_residual to avoid over-stuffing.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (fill_ratio * 10.0) * (1.0 - progress);

    // If this is the last chance to fit the item in existing bins, significantly lower the score
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // We prioritize bins that leave the smallest leftover space.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of lookahead
    // If the post_residual is a multiple of the next item, we create a "perfect" bin.
    if next_item_size > 0 {
        if post_residual % next_item_size == 0 {
            score -= 40.0;
        }
        // Penalize if the next item is significantly larger than current post_residual
        if next_item_size > post_residual {
            score += 20.0;
        }
    }

    // 3. Fragmentation Avoidance: Penalize residuals smaller than the smallest likely items (10)
    // If a bin has a residual that is "useless" (too small for common items), heavily penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. New Bin Thresholding:
    // Only open a new bin if the current best available fit is very poor (post_residual > 40)
    // or if we are at the end of the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Must open
        } else {
            score += 50.0; // Discourage opening new bin if existing ones fit
        }
    }

    // 5. Density Balancing:
    // Favor bins that align with the global mean residual to keep bin usage uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    // 6. Progression Scaling:
    // As the stream nears completion, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit any common item (e.g., < 10),
    // it creates "orphaned" space. We penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Best-Fit Bias: Encourage tightly packed bins by rewarding smaller post_residuals.
    // However, avoid the "new bin" trap by checking if this is a new bin (bin_residual == bin_capacity).
    if bin_residual != bin_capacity {
        // Reward bins that are nearing capacity
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    } else {
        // Penalize opening a new bin if other bins can accommodate the item.
        if fitting_bins_count > 0 {
            score += 45.0;
        }
    }

    // 3. Lookahead Coupling: If the next item is large, prioritize keeping space open.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Global Pressure: As we approach the end of the stream, prioritize closing bins
    // over maintaining multiple partially empty ones.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly from the mean
    // to encourage uniform bin usage.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals that are too small for any likely future item).
    // If post_residual is < 10, it is likely unusable.
    if post_residual < 10 {
