    // 2. Lookahead optimization: If the next item can fit perfectly or near-perfectly into the 
    // resulting post_residual, reward this bin placement heavily.
    if next_item_size > 0 {
        let fit_diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_diff * 0.5;

        // If post_residual is exactly the next item, prioritize this bin strongly.
        if post_residual == next_item_size {
