    // 3. Balance the load across bins: discourage opening new bins if there are existing options,
    // but penalize filling a bin to the point where it becomes "starved" relative to the mean.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize it based on how many bins are already open.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // If we are placing in an existing bin, favor those that move the bin residual 
        // closer to the global mean residual to keep bin states uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 4. Critical thresholding: If this is the only bin that fits the item, make it extremely attractive
    // to prevent unnecessary bin creation, unless the post_residual is disastrously small.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression scaling: As the stream nears the end, be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Favor smaller post-residuals (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too "fragile" (post_residual < next_item_size)
    // We want to avoid leaving a gap that cannot accommodate the next known item.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Heuristic: If we are near the end of the stream, prioritize filling existing bins
    // regardless of optimality to prevent stranded items.
    if progress > 0.85 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // Dynamic constraint: Penalize opening a new bin heavily unless it's necessary.
    // We balance the desire to pack tightly vs the desire to keep bin count low.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong discouragement: Only open a new bin if the current best fit is truly abysmal
            // (e.g., leaving a gap that is useless for any likely future item).
            score += 25.0 + (mean_residual * 0.5);
        } else {
            // Necessary to open a new bin
            score = 0.0;
        }
    } else {
        // Reward bins that bring the mean residual closer to the next_item_size
        // This keeps the "open" bins in a state that is likely to accept future items.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Final adjustment: penalize bins that become nearly empty (fragmentation)
    if post_residual > 80 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
