    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        // We increase this cost as progress approaches 1.0 to force consolidation.
        score += 85.0 + (progress * 40.0);
    }

    // Heuristic coupling: If this is the ONLY bin that fits the item, 
    // significantly discount the score to prioritize using existing capacity 
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Coupling with global state: 
    // If the mean residual is high, we are being too wasteful. 
    // Penalize bins that increase the mean residual further.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

