        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Progressive Tightening: As the stream nears completion, become more aggressive at filling 
    // existing bins to avoid opening new ones at the end.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the post_residual (Best Fit), but we apply penalties for 
    // leaving "slivers" that are too small to be useful for common upcoming items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is almost empty (new bin overhead)
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (no fitting bins) 
        // or if our current open bins are very constrained.
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        } else {
            score += 5.0;
        }
    }

    // Lookahead: If the next item doesn't fit in the post_residual, 
    // penalize the residual to favor bins that can accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Dead space penalty: If the post_residual is between 1 and 9, it is likely 
    // unusable given the minimum item size (10). Penalize this specifically.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 - (post_residual as f64 * 2.0);
    }

    // Global state: If we have many open bins, prioritize closing gaps 
    // in bins that are already partially filled (lower mean_residual).
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // Critical constraint: If this is the only bin that fits the item, 
    // give it a massive priority boost to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead space" (post_residual) exponentially.
    // Near the end of the stream, prioritize tighter packing to reduce total bin count.
    let dead_space_penalty = post_res.powf(1.5 + (0.5 * progress));

    // Reward bins that can accommodate the next item (lookahead).
    // If next_item_size fits in the remaining space, subtract from score.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        (next_item_size as f64) * (1.0 + progress)
    } else {
        0.0
    };

    // Discourage opening new bins early unless the fit is poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    let new_bin_penalty = if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low
        // or if we have very few fitting options.
        let base_new_bin_cost = 45.0;
        base_new_bin_cost + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Heavily penalize leaving a bin with a very small residual that is likely unusable (e.g., < 10)
    // unless it is the very last item in the stream.
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 && progress < 0.95 {
        (10.0 - post_residual as f64) * 5.0
    } else {
        0.0
    };

    // Combine metrics: Lower score is better.
    let score = dead_space_penalty 
                - lookahead_bonus 
                + new_bin_penalty 
                + fragmentation_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
