    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We add a non-linear penalty for leaving small, unusable gaps (1-9)
    let gap_penalty = if post_res > 0.0 && post_res < 10.0 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size cannot fit in current post_residual, 
    // penalize this bin to favor keeping it open for the next item (if it fits).
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing open bins.
    let progress_weight = 1.0 + (progress * 2.0);

    // Penalize opening a new bin (bin_residual == bin_capacity) 
    // unless the current open bins are too full to accommodate future items efficiently.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 10.0) + (mean_residual * 0.5)
    } else {
