    };

    // Interaction term: If fitting_bins_count is low, we are running out of options; 
    // lower the score to prioritize closing the current bin if it's a good fit.
    let scarcity_factor = if fitting_bins_count <= 1 { -5.0 } else { 0.0 };

    let score = (post_res * progress_weight) 
        + gap_penalty 
        + lookahead_penalty 
        + new_bin_penalty 
        + scarcity_factor;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
