    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item cannot fit in this post_residual, 
    // but could fit in a different open bin, penalize the current choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is perfect or necessary.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Always open the first bin
        } else {
            // Only open a new bin if the average residual of existing bins is already very small
            // or if the current item is very large.
            score += 45.0 + (mean_residual * 0.5);
        }
    } else {
        // 4. Efficiency Bonus: Prefer bins that maintain a high density of usage.
        // A smaller post_residual is usually better, but we favor filling bins tightly.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // 5. Last Chance Heuristic: If this is the only bin that can fit the item, 
        // give it a slight preference boost to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 6. Progression Scaling: As we approach the end of the stream, 
    // prioritize tighter packing to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only do it if the fit is perfect or necessary
    if bin_residual == bin_capacity {
