    }

    // 5. New Bin Penalty: If this is a new bin (bin_residual == bin_capacity),
    // apply a significant penalty unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; // Discourage opening new bins if alternatives exist
        } else {
            score -= 10.0; // Necessary evil
        }
    }

    // 6. Balance: Encourage using bins that stay close to the mean residual
    // to maintain uniform density across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We penalize the "new bin" case (bin_residual == bin_capacity) 
    // by scaling it based on the remaining stream capacity.
    let mut score = post_res;

    // Penalty for creating a new bin:
    // If this is a new bin, we add a penalty that decreases as we near the end of the stream
    // to encourage consolidation, but remains high early on to force Best Fit.
    if bin_residual == bin_capacity {
