    // Dynamic density pressure:
    // If we have many open bins, we penalize creating or adding to bins that deviate 
    // significantly from the current mean_residual to promote bin homogeneity.
    if open_bins_count > 1 {
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2 * progress;
    }

    // Critical thresholding: 
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // we lower the score to prioritize closing the gap rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
