pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that likely won't fit future items)
    // Small residuals (1-9) are notoriously difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If the next item is large, prioritize keeping space open.
    // If next_item_size is large, we heavily penalize bins that leave very little space 
    // for that specific item, effectively forcing the packing of smaller items into 
    // tighter gaps first.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that leave exactly enough space for the next item (harmonic alignment)
            if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
                score -= 15.0;
            }
        }
    }

    // 3. Pressure Management: If we are running out of items, minimize open bins count.
    // If fitting_bins_count is 1, this is the last chance to use an existing bin. 
    // We heavily discount the score to prefer current bins over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Distribution Balancing: Bias towards bins that keep the mean_residual stable.
    // This prevents "bin-fragmentation" where some bins are very full and others are nearly empty.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Penalty: The "New Bin" call has bin_residual == bin_capacity.
    // We add a significant penalty to ensure we only open a new bin if the existing 
    // fit quality is extremely poor (e.g., leaving a tiny unusable fragment).
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
