    // 4. Fitting Bin Scarcity: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. New Bin Threshold: If we are evaluating a new bin (bin_residual == bin_capacity),
    // force a high penalty unless open bins are already very full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual < 30.0 {
            score += 60.0; // Discourage opening new bins if current ones have space
        } else {
            score += 10.0; // Moderate cost for a new bin
        }
    }

    // 6. Balance: Penalize bins that deviate from the mean_residual to keep bin fullness uniform.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses
    // to force consolidation in the later stages.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + (progress * 50.0));

    // Best-Fit Decreasing logic: reward small post_residuals, but apply a non-linear
    // penalty for "dead zones" (small residuals that are unlikely to fit future items).
    // If post_residual is very small (1-5), it is high-risk for fragmentation.
    let fragmentation_penalty = if post < 6.0 && post > 0.0 {
        (6.0 - post) * 15.0
    } else {
        0.0
    };

    // Lookahead coupling: If a future item is known, penalize bins that cannot fit it
    // or reward bins that create a perfect fit for the next item.
    let lookahead_score = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -15.0 * (1.0 - progress) // Reward bins that leave space for the next item
        } else {
            10.0 * progress // Penalize bins that block the next item
        }
    } else {
        0.0
    };

    // Balance open bins: avoid opening too many bins early, but permit it if 
    // it significantly improves the mean_residual of the set.
    let density_penalty = (open_bins_count as f64) * (1.0 - progress) * 2.0;

    let mut score = post + new_bin_penalty + fragmentation_penalty + lookahead_score + density_penalty;

    // If this is the last chance for the current item, aggressively reduce score
    // to prevent unnecessary new bin allocation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

