        score += (fitting_bins_count as f64) * 5.0;

        // If we are late in the stream, opening new bins is expensive.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 5. Harmonic Class Logic: Prefer bins that leave residuals divisible by common small item sizes (e.g., 10, 20).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 6. Final normalization: Favor filling bins to near-capacity.
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

