    // 1. Dead Space Penalty: If post_residual is small (1-9), it's highly likely to be wasted.
    // We penalize this heavily because items are at least size 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin to reduce the fragmentation impact.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Open Bin Pressure: If we have many open bins, we should be more aggressive 
    // about filling them rather than opening new ones.
    if bin_residual == bin_capacity {
        // New bin penalty: scales with the number of open bins and the mean residual.
        // If mean_residual is high, we have enough space elsewhere.
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // Existing bin bonus: reward using bins that are already "tight".
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Critical Threshold: If this is the only bin that can fit the item, 
    // prioritize it strongly to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a heavy penalty based on current open bin density.
    // This discourages opening new bins unless all existing bins are poorly suited.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    } else {
        // 2. Best-Fit logic: Penalize large post_residuals (wasted space).
        // Bias towards tight fits, but reserve capacity for the lookahead.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward: This bin can perfectly or near-perfectly accommodate the next item.
                score -= (next_item_size as f64) * 0.8;
            } else {
                // Penalty: Creating a dead space that cannot fit the immediate next item.
                score += (post_residual as f64) * 0.5;
            }
        }

        // 3. Adaptive balancing: If many bins are open, try to pack tighter to empty bins.
        // If fitting_bins_count is low, prioritize filling this bin to avoid fragmentation.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // 4. Global residual pressure: If current bin is emptier than average, 
        // prioritize filling it to keep the mean_residual stable.
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // 5. Progression scaling: As we reach the end of the stream, be more aggressive
    // about fitting items into existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
