            score -= (100.0 - space_left_after_next as f64) * 0.5;
        } else {
            // If the next item doesn't fit, we penalize slightly to encourage
            // using bins that might accommodate the next item better.
            score += 5.0;
        }
    }

    // Global state awareness:
    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // We should prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New bin logic:
    // Only open a new bin if the current fit is extremely poor (large waste).
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // High threshold: only open a new bin if the current fit is worse than 
