        0.0
    };

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current placement.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * 0.8
    } else {
        0.0
    };

    // Interaction with mean_residual: avoid bins that deviate significantly from average,
    // as packing them tightly is statistically harder.
    let variance_penalty = (post_res - mean_residual).abs() * 0.2;

    // Final score: minimize post_residual, while adjusting for the penalties above.
    let mut score = post_res + new_bin_penalty + dead_space_penalty + lookahead_penalty + variance_penalty;

    // If this is the last chance to fit an item into an existing bin, reduce penalty to prioritize fitting.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, so it stays as the baseline.

    // 2. Harmonic Class logic: Identify "tightness" thresholds
    // Punish bins that leave small, unusable slivers (e.g., 1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 3. Lookahead coupling: If next_item_size is large, favor larger post_residuals
    // If next_item_size is small, favor very tight fits now.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Cannot fit next item, penalize if we could have fit it in a different bin
            score += 20.0;
        } else {
            // Can fit next item, reward this bin
            score -= 15.0;
        }
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item,
    // we should prioritize it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New bin handling: Only open a new bin if the current "best" fit is truly awful
    // (High post_residual or leaves a useless sliver).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is high; only accept if we are forced or 
        // if existing bins are heavily fragmented.
        score += 40.0 + (mean_residual * 0.5);
    }

    // 6. Progression weighting: As we approach the end of the stream, 
    // prioritize packing efficiency (lower residuals) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small to fit the smallest expected 
    // items (heuristic threshold of 10), it becomes "dead space". We penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit/First-Fit Pressure: Penalize opening a new bin if other bins are available.
    // If this is a new bin (bin_residual == bin_capacity) and we have fitting options, 
    // apply a significant penalty to discourage premature new bin creation.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 120.0;
    }

    // 3. Lookahead Optimization: If the next item can fit in the current post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Global Density Management: As the stream progresses, favor packing into 
    // existing bins to reduce the open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 5. Mean Residual Alignment: Penalize bins that deviate too far from the 
    // current mean_residual to keep bin states uniform (improves future fit chances).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost is post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead zones" (small residuals that cannot fit future items).
    // If post_residual is < 10, it is likely unusable for any incoming item (min size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead optimization: If the next item fits into the current post_residual,
    // we reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Heuristic for new bin allocation:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // it's the only option or the current fitting bins are very poor (high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open
        } else {
            // Only open a new bin if the average residual is already very small
            // and we are early in the stream, or if existing bins are poor fits.
            score += 45.0 + (mean_residual * 0.5);
        }
    }

    // 5. Urgency factor: If fitting_bins_count is 1, we are at a critical decision point.
    // If this is the last chance for the current item, we reduce the score to ensure 
    // we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Global progression adjustment: As we reach the end of the stream, 
    // prioritize filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 30.0);
    }

    score
}
